    ('ad216a23-c9d1-5eac-91a7-b4753e831bcd'::uuid, 'Quiz — Colette — comment on célèbre sans embellir', 'Français', '1re', 'Sido, suivi de Les Vrilles de la vigne - Partie 2', '04d926f0-cf9b-5303-a1a6-da8202a92944'::uuid),
