    ('fc1de1c7-fd60-5971-bf60-a137edf01eb2'::uuid, 'Quiz — Sarraute, 1982 — une amitié détruite par une intonation', 'Français', '1re', 'Pour un oui ou pour un non', '80641d59-3a83-598a-8977-3f85aae01883'::uuid),
