    ('221ba00f-323d-5e5c-9d14-394bb65bb68c'::uuid, 'Quiz — Deux propositions à égalité', 'Français', '1re', 'Juxtaposition et coordination', '52b09707-a16a-59ca-8643-d802691b5628'::uuid),
    ('5b646f1e-452e-58bd-8e9b-3390dc586fb4'::uuid, 'Quiz — Elle complète un nom, comme un adjectif', 'Français', '1re', 'La proposition subordonnée relative', 'b0dd1762-4395-5575-a51c-276c5075de17'::uuid),
    ('6c1e6638-1bb3-5c96-a64b-3e3dde1f649c'::uuid, 'Quiz — Elle complète un verbe, comme un COD', 'Français', '1re', 'La proposition subordonnée conjonctive complétive', 'f83a3774-a0ca-589d-8d0d-cb2c8fa7fa20'::uuid),
    ('c85e2bc7-1443-5ec8-86fd-95667ae6c4da'::uuid, 'Quiz — Elles complètent la phrase entière', 'Français', '1re', 'Les propositions subordonnées circonstancielles', '6b48e157-ad81-52df-b45a-e479cdccc756'::uuid),
    ('7aa1285d-7e08-5fbd-9816-1c47d571304a'::uuid, 'Quiz — Sur quoi porte la question ?', 'Français', '1re', 'L’interrogation totale et partielle', '646acd1a-5e39-5c9f-8ed4-2146892b93bc'::uuid),
    ('3e33051e-c4ca-571e-aa55-a5e3b2c2897b'::uuid, 'Quiz — La question rapportée change de forme', 'Français', '1re', 'L’interrogation directe et indirecte', '5dbc65e1-6dcb-57c2-bb24-82122b06bdee'::uuid),
    ('fd942bf6-ffdc-58b9-9289-f693f7374418'::uuid, 'Quiz — Dire non, et de combien', 'Français', '1re', 'L’expression de la négation', 'cf7e42bb-a885-54b4-922c-cc3d8cc667b5'::uuid),
    ('6fceba59-9530-5727-bafe-f784f25ee389'::uuid, 'Quiz — Deux points en cinq minutes, si l’on suit l’ordre', 'Français', '1re', 'La méthode de la question de grammaire', '4a9f6237-b4c9-5eed-a7b9-0e79540b05a5'::uuid),
    ('9df56e6c-5830-52df-b217-f30b666372eb'::uuid, 'Quiz — Le minimum vital, sans lequel rien ne tient', 'Français', '1re', 'Les fonctions grammaticales à savoir nommer', '42ea7f47-9fbd-5b12-93f3-3a05952204bc'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('9b6f2f36-cbf9-5dbd-a6c8-de50f62d39c7'::uuid, '5beabcb1-4e2c-5a94-aa5b-9f7e23947b44'::uuid, 'Combien de syllabes compte un alexandrin ?', 'mcq', '["12","10","8","14"]'::jsonb, 0, 'L’octosyllabe en compte 8, le décasyllabe 10 : ce sont les trois mètres à connaître.', 1),
    ('933da326-96a8-5bde-9370-846b26f1dc04'::uuid, '5beabcb1-4e2c-5a94-aa5b-9f7e23947b44'::uuid, 'Comment appelle-t-on la coupe qui sépare les deux hémistiches de l’alexandrin ?', 'mcq', '["La césure","L’élision","La diérèse","Le rejet"]'::jsonb, 0, 'Elle tombe classiquement après la sixième syllabe.', 2),
    ('b723e50c-d140-5245-aa84-138eea77d681'::uuid, '5beabcb1-4e2c-5a94-aa5b-9f7e23947b44'::uuid, 'Qu’est-ce qu’un enjambement ?', 'mcq', '["La phrase se poursuit au vers suivant sans pause","Deux vers riment ensemble","Une syllabe est supprimée","Un vers est plus long que les autres"]'::jsonb, 0, 'Quand le débordement est bref et mis en valeur, on parle de rejet.', 3),
    ('513af73e-2fe1-5c05-9bb5-277739b46943'::uuid, '5beabcb1-4e2c-5a94-aa5b-9f7e23947b44'::uuid, 'Quelle est la structure d’un sonnet ?', 'mcq', '["Deux quatrains puis deux tercets","Trois quatrains puis un distique","Quatre tercets","Deux tercets puis deux quatrains"]'::jsonb, 0, 'Forme héritée de la Renaissance italienne, encore dominante au XIXe siècle.', 4),
    ('536b4e31-daca-5b1c-895a-7f7abb28a9d3'::uuid, '5beabcb1-4e2c-5a94-aa5b-9f7e23947b44'::uuid, 'Qu’est-ce qu’une synesthésie ?', 'mcq', '["Une correspondance entre des sensations de sens différents","Une répétition en début de vers","Un rapprochement de deux mots contradictoires","Une comparaison sans outil de comparaison"]'::jsonb, 0, 'C’est la figure des « Correspondances » de Baudelaire : parfums, couleurs et sons se répondent.', 5),
    ('cb58997d-a2dc-5765-8d10-bca48101283b'::uuid, '5beabcb1-4e2c-5a94-aa5b-9f7e23947b44'::uuid, 'Comment nomme-t-on la disposition de rimes ABBA ?', 'mcq', '["Rimes embrassées","Rimes croisées","Rimes plates","Rimes suivies"]'::jsonb, 0, 'ABAB donne des rimes croisées, AABB des rimes plates ou suivies.', 6),
    ('35d2d78a-7f01-5b8f-8aff-6a017c8c336e'::uuid, '5beabcb1-4e2c-5a94-aa5b-9f7e23947b44'::uuid, 'Le parcours associé est un simple thème décoratif, sans effet sur l’épreuve.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il oriente le sujet de dissertation : le connaître, c’est déjà avoir le plan de la moitié des sujets possibles.', 7),
    ('7bf034b4-d97a-53a8-8f8a-544548a92e42'::uuid, '5beabcb1-4e2c-5a94-aa5b-9f7e23947b44'::uuid, 'Quelle méthode l’explication linéaire impose-t-elle à l’oral ?', 'mcq', '["Suivre le mouvement du texte du début à la fin","Regrouper les remarques par thèmes","Comparer le texte à une autre œuvre","Résumer le texte puis donner son avis"]'::jsonb, 0, 'Le plan thématique plaqué est la faute la plus sanctionnée de l’exercice.', 8),
    ('bcc878c3-631a-5675-9c42-68e1df4435af'::uuid, '6e37eb72-fcdb-5337-ba3d-feb88aac553d'::uuid, 'Combien de poèmes composent les Cahiers de Douai ?', 'mcq', '["22","12","50","30"]'::jsonb, 0, 'Recopiés en deux liasses chez Paul Demeny, à Douai, en 1870.', 1),
    ('82bd5e3b-04b6-5ca1-aa6b-1665bef726cf'::uuid, '6e37eb72-fcdb-5337-ba3d-feb88aac553d'::uuid, 'Quel âge a Rimbaud lorsqu’il écrit ces poèmes ?', 'mcq', '["Quinze et seize ans","Vingt ans","Dix-huit ans","Vingt-cinq ans"]'::jsonb, 0, 'C’est un argument central du parcours : l’émancipation est d’abord celle d’un adolescent.', 2),
    ('9f893a39-df5f-5a95-b120-29968e0d2ae1'::uuid, '6e37eb72-fcdb-5337-ba3d-feb88aac553d'::uuid, 'Quel est le parcours associé à l’œuvre ?', 'mcq', '["Émancipations créatrices","Alchimie poétique : la boue et l’or","La célébration du monde","Modernité poétique ?"]'::jsonb, 0, 'Émancipation de l’adolescent, du citoyen et du poète : les trois se lisent dans les mêmes textes.', 3),
    ('eda9b5df-075c-587b-835d-63a158de00d0'::uuid, '6e37eb72-fcdb-5337-ba3d-feb88aac553d'::uuid, 'Sur quelle chute se termine « Le Dormeur du val » ?', 'mcq', '["Deux trous rouges au côté droit","Un baiser volé","Une aube d’été","Un cri de révolte"]'::jsonb, 0, 'Treize vers de nature riante préparent la révélation du dernier : le soldat est mort.', 4),
    ('7c9ec750-4f06-5daa-82d4-1043fd6ef84d'::uuid, '6e37eb72-fcdb-5337-ba3d-feb88aac553d'::uuid, 'Quel événement historique traverse le recueil ?', 'mcq', '["La guerre franco-prussienne de 1870","La Révolution de 1789","La Commune de Paris de 1871","La Première Guerre mondiale"]'::jsonb, 0, 'La chute du Second Empire nourrit les poèmes satiriques comme « Rages de Césars ».', 5),
    ('9e07ad87-f9ff-51ab-98c2-702e0dadc2ed'::uuid, '6e37eb72-fcdb-5337-ba3d-feb88aac553d'::uuid, 'Dans « Ma Bohème », comment le poète se présente-t-il ?', 'mcq', '["En vagabond, les poings dans ses poches crevées","En soldat blessé","En savant enfermé dans sa bibliothèque","En amant éconduit"]'::jsonb, 0, 'La fugue devient la condition même de l’écriture.', 6),
    ('b4c32c7f-adfa-5736-ab85-c3033cbcb9c0'::uuid, '6e37eb72-fcdb-5337-ba3d-feb88aac553d'::uuid, 'Rimbaud rejette entièrement les formes classiques dans ce recueil.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il écrit des sonnets et des alexandrins réguliers : il les fait craquer de l’intérieur, par les enjambements et le vocabulaire.', 7),
    ('07bc5889-6d73-5e56-beac-a7129e27d13b'::uuid, '6e37eb72-fcdb-5337-ba3d-feb88aac553d'::uuid, 'Quel poème retourne les codes de la beauté idéale en laideur crue ?', 'mcq', '["Vénus Anadyomène","Sensation","Au Cabaret-Vert","Le Forgeron"]'::jsonb, 0, 'Le sonnet, forme noble, y sert une description volontairement répugnante.', 8),
    ('383e44a9-3beb-5771-91c1-b78377290bf1'::uuid, '7aa1c7e7-6485-5ea1-abb6-310b1780a518'::uuid, 'Quelle est la particularité de La rage de l’expression ?', 'mcq', '["Elle publie les brouillons et les reprises du poète","Elle ne contient que des sonnets","Elle raconte la vie de l’auteur","Elle est écrite en vers réguliers"]'::jsonb, 0, 'Le livre est fait de carnets datés : on voit le poème se chercher.', 1),
    ('4150edea-adcc-599a-9755-5fa7e922c224'::uuid, '7aa1c7e7-6485-5ea1-abb6-310b1780a518'::uuid, 'Quel est le parcours associé à l’œuvre ?', 'mcq', '["Dans l’atelier du poète","Émancipations créatrices","La poésie, la nature, l’intime","Les Mémoires d’une âme"]'::jsonb, 0, 'L’atelier est ici littéral : ce sont les séances de travail elles-mêmes qui sont publiées.', 2),
    ('1a103826-9b06-5589-b21a-43f7f5369298'::uuid, '7aa1c7e7-6485-5ea1-abb6-310b1780a518'::uuid, 'Quels objets Ponge choisit-il de décrire ?', 'mcq', '["Des objets modestes : un pin, un œillet, une guêpe, un mimosa","Des paysages grandioses","Des figures mythologiques","Des scènes historiques"]'::jsonb, 0, 'Le choix du minuscule est une prise de position contre le lyrisme du grandiose.', 3),
    ('9a392361-2338-5f19-a010-45cec5d04442'::uuid, '7aa1c7e7-6485-5ea1-abb6-310b1780a518'::uuid, 'Que refuse Ponge en décrivant les choses ?', 'mcq', '["De les humaniser et d’en faire le miroir de ses sentiments","De les nommer précisément","D’utiliser le dictionnaire","De les observer directement"]'::jsonb, 0, 'C’est le contraire du paysage romantique, où la nature reflète l’âme du poète.', 4),
    ('427f13bd-06cc-553f-86ba-8e912497d2ea'::uuid, '7aa1c7e7-6485-5ea1-abb6-310b1780a518'::uuid, 'Que désigne le mot « rage » du titre ?', 'mcq', '["L’acharnement du poète à reprendre son texte","La colère politique","La violence de la nature décrite","La haine du lecteur"]'::jsonb, 0, 'L’échec de la langue à saisir l’objet est intégré à l’œuvre, il en est le sujet.', 5),
    ('4c570ac8-8620-5cbb-aaf7-e2ba1682a871'::uuid, '7aa1c7e7-6485-5ea1-abb6-310b1780a518'::uuid, 'Quel outil accompagne l’écriture de Ponge ?', 'mcq', '["Le dictionnaire, notamment le Littré","Le carnet de voyage","Le journal intime","Le traité de versification"]'::jsonb, 0, 'L’étymologie et les définitions successives sont des matériaux du poème.', 6),
    ('2dfd182d-7444-5da5-9c31-b2705df719f5'::uuid, '7aa1c7e7-6485-5ea1-abb6-310b1780a518'::uuid, 'Les textes de La rage de l’expression sont tous écrits en vers.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La prose domine, mêlée à des notes brutes et à quelques passages versifiés.', 7),
    ('06a2f1a8-b9b4-5281-853e-0de9619f68ea'::uuid, '7aa1c7e7-6485-5ea1-abb6-310b1780a518'::uuid, 'En quelle année l’œuvre paraît-elle ?', 'mcq', '["1952","1942","1938","1961"]'::jsonb, 0, 'Elle rassemble des textes écrits entre 1938 et 1944.', 8),
    ('27a8f678-ebb3-587d-bb83-7d0e5ff9a1e3'::uuid, '4cb19ea9-30ee-55cd-b057-a9ff964ea3ae'::uuid, 'En quelle année Mes forêts a-t-il été publié ?', 'mcq', '["2021","1998","2010","1952"]'::jsonb, 0, 'C’est la première œuvre d’une autrice vivante inscrite au programme du bac de français.', 1),
    ('422690ac-ff33-594c-88ce-aad4497b076e'::uuid, '4cb19ea9-30ee-55cd-b057-a9ff964ea3ae'::uuid, 'De quelle nationalité est Hélène Dorion ?', 'mcq', '["Québécoise","Française","Belge","Suisse"]'::jsonb, 0, 'Elle est une des grandes voix de la poésie contemporaine de langue française.', 2),
    ('3f3b04f2-c9c7-5a3f-b3c7-f9de4530d1e0'::uuid, '4cb19ea9-30ee-55cd-b057-a9ff964ea3ae'::uuid, 'Combien de sections composent le recueil ?', 'mcq', '["Quatre","Deux","Sept","Douze"]'::jsonb, 0, 'Elles sont précédées d’un poème liminaire et ouvertes par des citations en exergue.', 3),
    ('b021c097-008f-5af9-980d-0b627824777c'::uuid, '4cb19ea9-30ee-55cd-b057-a9ff964ea3ae'::uuid, 'Quel est le parcours associé à l’œuvre ?', 'mcq', '["La poésie, la nature, l’intime","Dans l’atelier du poète","Émancipations créatrices","La célébration du monde"]'::jsonb, 0, 'Le recueil fait tenir ces trois termes ensemble, jamais séparément.', 4),
    ('0a117c20-7df7-533a-8280-d2f499a1e850'::uuid, '4cb19ea9-30ee-55cd-b057-a9ff964ea3ae'::uuid, 'Que signifie le possessif du titre « Mes forêts » ?', 'mcq', '["La forêt est un paysage intérieur autant qu’extérieur","La poétesse possède une forêt","Il s’agit de forêts imaginaires","Le titre est ironique"]'::jsonb, 0, 'L’arbre — racines, cernes, écorce — sert à dire une vie humaine.', 5),
    ('e194c855-13a0-5dee-b3ed-4df5dd8e6f7e'::uuid, '4cb19ea9-30ee-55cd-b057-a9ff964ea3ae'::uuid, 'Quelle forme prennent les poèmes du recueil ?', 'mcq', '["Des vers libres, presque sans ponctuation","Des sonnets réguliers","Des poèmes en prose","Des alexandrins rimés"]'::jsonb, 0, 'Les blancs typographiques et les anaphores donnent au texte sa pulsation.', 6),
    ('aa13f52c-5663-55e2-b27a-5036357ed173'::uuid, '4cb19ea9-30ee-55cd-b057-a9ff964ea3ae'::uuid, 'La dimension écologique du recueil prend la forme d’un discours militant.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle passe par la conscience d’appartenir au vivant : la perte de la forêt est vécue comme une perte intime.', 7),
    ('8a99d019-d7e3-5114-b856-1757f92683b7'::uuid, '4cb19ea9-30ee-55cd-b057-a9ff964ea3ae'::uuid, 'Quel deuil traverse le recueil ?', 'mcq', '["Celui du père","Celui d’un enfant","Celui d’un ami poète","Aucun deuil"]'::jsonb, 0, 'Il nourrit la deuxième section, « Une chute de galets ».', 8),
    ('98ef9f79-9ee2-56ce-ad3e-27314c127377'::uuid, '81f07ebd-9dfa-5c11-9abf-f32396b58fc5'::uuid, 'À quoi s’adresse une argumentation qui vise à convaincre ?', 'mcq', '["À la raison du lecteur","À ses émotions","À son imagination","À sa mémoire"]'::jsonb, 0, 'Persuader s’adresse aux émotions ; délibérer pèse le pour et le contre.', 1),
    ('142b506e-39e2-54a8-9e14-00a36956d8ad'::uuid, '81f07ebd-9dfa-5c11-9abf-f32396b58fc5'::uuid, 'Qu’est-ce que l’argumentation indirecte ?', 'mcq', '["Défendre une thèse par le détour de la fiction","Écrire un essai sans plan","Citer un auteur célèbre","Répondre à un adversaire par lettre"]'::jsonb, 0, 'Fable, conte philosophique, utopie, lettre fictive : le détour contourne aussi la censure.', 2),
    ('dd61426a-8197-5df4-8bc7-cc4042bfdfb1'::uuid, '81f07ebd-9dfa-5c11-9abf-f32396b58fc5'::uuid, 'Quel procédé consiste à faire décrire la société française par un visiteur étranger ?', 'mcq', '["Le regard éloigné","La maxime","L’antiphrase","La périphrase"]'::jsonb, 0, 'Ce que l’habitude rend invisible redevient étrange, donc discutable.', 3),
    ('f8e988a5-9426-5521-8bab-874a3dee2bd9'::uuid, '81f07ebd-9dfa-5c11-9abf-f32396b58fc5'::uuid, 'Qu’est-ce qu’une antiphrase ?', 'mcq', '["Dire le contraire de ce que l’on pense pour être compris ironiquement","Répéter un mot en début de phrase","Rapprocher deux termes opposés","Exagérer volontairement"]'::jsonb, 0, 'C’est le principal support de l’ironie.', 4),
    ('eac47909-54fa-5ec0-8b6b-f05a9a528de2'::uuid, '81f07ebd-9dfa-5c11-9abf-f32396b58fc5'::uuid, 'Quel siècle correspond aux Lumières ?', 'mcq', '["Le XVIIIe","Le XVIe","Le XVIIe","Le XIXe"]'::jsonb, 0, 'Le XVIe est celui de l’humanisme, le XVIIe celui des moralistes classiques.', 5),
    ('315d7b3f-135b-56e9-a331-1bd787e6e2ac'::uuid, '81f07ebd-9dfa-5c11-9abf-f32396b58fc5'::uuid, 'Quel genre bref les moralistes du XVIIe siècle privilégient-ils ?', 'mcq', '["La maxime et le portrait","Le roman-fleuve","La tragédie en vers","L’essai autobiographique"]'::jsonb, 0, 'La Rochefoucauld et La Bruyère en sont les maîtres.', 6),
    ('8dc8f193-d13e-5176-b8c6-e13a2cf6d75a'::uuid, '81f07ebd-9dfa-5c11-9abf-f32396b58fc5'::uuid, 'Un texte peut viser à la fois à convaincre et à persuader.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est même le cas le plus fréquent : l’analyse consiste à déterminer lequel des deux domine.', 7),
    ('7d2598bf-49b1-5803-ba76-69198ba1be30'::uuid, '81f07ebd-9dfa-5c11-9abf-f32396b58fc5'::uuid, 'Qu’est-ce qu’un modalisateur ?', 'mcq', '["Un mot qui marque le degré d’adhésion de l’auteur à ce qu’il dit","Un connecteur logique","Une figure d’insistance","Un synonyme atténué"]'::jsonb, 0, '« Peut-être », « sans doute », « il est certain que » : ils dessinent la position de l’énonciateur.', 8),
    ('dd2b861c-2fe0-563f-be2d-5424e2b476e5'::uuid, '3e1fedec-d081-5817-9f3b-114d9ba5f65a'::uuid, 'Quelle question centrale le Discours de la servitude volontaire pose-t-il ?', 'mcq', '["Pourquoi les peuples consentent-ils à obéir à un seul homme ?","Comment un roi doit-il gouverner ?","Faut-il tuer le tyran ?","Quelle est la meilleure constitution ?"]'::jsonb, 0, 'Le renversement est là : ce n’est pas le tyran qui tient le peuple, c’est le peuple qui le porte.', 1),
    ('bdf18d0c-1ef6-5b5d-a920-c53eea06894e'::uuid, '3e1fedec-d081-5817-9f3b-114d9ba5f65a'::uuid, 'Quelle solution La Boétie propose-t-il contre la tyrannie ?', 'mcq', '["Cesser de consentir, sans violence","Assassiner le tyran","Organiser une armée","Attendre un souverain plus juste"]'::jsonb, 0, '« Soyez résolus de ne servir plus, et vous voilà libres. »', 2),
    ('d937d938-e6cc-52b6-a328-359e5b77f47b'::uuid, '3e1fedec-d081-5817-9f3b-114d9ba5f65a'::uuid, 'Quelle est, selon La Boétie, la première cause de la servitude ?', 'mcq', '["La coutume et l’habitude","La peur des armes","La religion","La pauvreté"]'::jsonb, 0, 'On naît sous le joug et l’on croit qu’il est naturel.', 3),
    ('8ee9c62b-b11b-5db4-a416-70b0cfb68274'::uuid, '3e1fedec-d081-5817-9f3b-114d9ba5f65a'::uuid, 'Comment La Boétie nomme-t-il le système d’intérêts qui soutient le tyran ?', 'mcq', '["Une pyramide de complices, des cinq ou six aux six mille","Une armée de mercenaires","Un conseil de sages","Une assemblée élue"]'::jsonb, 0, 'Chaque étage profite de l’étage supérieur : le tyran n’a presque rien à faire.', 4),
    ('c163d4eb-7394-5818-a512-a758cc61dc0f'::uuid, '3e1fedec-d081-5817-9f3b-114d9ba5f65a'::uuid, 'Quel rôle jouent les jeux et les fêtes selon La Boétie ?', 'mcq', '["Ils divertissent le peuple pour mieux l’asservir","Ils entretiennent la santé publique","Ils permettent la révolte","Ils n’ont aucun rôle politique"]'::jsonb, 0, 'Le divertissement est le second ressort de la servitude volontaire.', 5),
    ('eb4d1890-a6a0-5b95-95ce-a28a9c6b40ac'::uuid, '3e1fedec-d081-5817-9f3b-114d9ba5f65a'::uuid, 'À quel écrivain La Boétie était-il intimement lié ?', 'mcq', '["Montaigne","Rabelais","Ronsard","Du Bellay"]'::jsonb, 0, 'Montaigne lui consacre le chapitre « De l’amitié » des Essais.', 6),
    ('176ae3ba-e0aa-5d26-9800-f794507fe9eb'::uuid, '3e1fedec-d081-5817-9f3b-114d9ba5f65a'::uuid, 'Le Discours a été publié du vivant de son auteur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il circule d’abord manuscrit et paraît après sa mort, notamment repris par des pamphlétaires protestants.', 7),
    ('a901651a-d5a9-557f-bcb7-315bc8c3a4a1'::uuid, '3e1fedec-d081-5817-9f3b-114d9ba5f65a'::uuid, 'Quel est l’autre titre traditionnel de l’œuvre ?', 'mcq', '["Le Contr’un","Le Prince","L’Utopie","Le Léviathan"]'::jsonb, 0, 'Titre qui dit la thèse : tout le texte est dirigé contre le pouvoir d’un seul.', 8),
    ('3fd38dd8-2ac8-5b67-90a0-d0c33fefc875'::uuid, 'db775e93-5692-5b2b-ac37-a492d0d44206'::uuid, 'Quelle forme littéraire Fontenelle choisit-il ?', 'mcq', '["Le dialogue, sur six soirs","Le traité en chapitres numérotés","La lettre ouverte","Le conte philosophique"]'::jsonb, 0, 'Le dialogue rend visible le chemin de la compréhension, objections comprises.', 1),
    ('874e36a9-d50b-5517-8065-b9f02db6dc77'::uuid, 'db775e93-5692-5b2b-ac37-a492d0d44206'::uuid, 'Qui est l’interlocutrice du philosophe ?', 'mcq', '["Une marquise","Une religieuse","Une astronome","Sa propre fille"]'::jsonb, 0, 'Elle représente le public mondain, souvent féminin, tenu à l’écart des savoirs savants.', 2),
    ('d44d86ea-b6ca-5899-b934-664775209761'::uuid, 'db775e93-5692-5b2b-ac37-a492d0d44206'::uuid, 'Quel système astronomique l’ouvrage expose-t-il ?', 'mcq', '["Le système de Copernic","Le système de Ptolémée","La théorie de la relativité","Le système de Tycho Brahe"]'::jsonb, 0, 'La Terre tourne autour du Soleil : l’ouvrage le rend accessible à un public non savant.', 3),
    ('c5f9b559-3a0d-527c-a280-9b55809fd108'::uuid, 'db775e93-5692-5b2b-ac37-a492d0d44206'::uuid, 'Quelle hypothèse audacieuse le livre défend-il ?', 'mcq', '["Les autres mondes pourraient être habités","La Terre est plate","Le Soleil tourne autour de la Terre","Les étoiles sont des reflets"]'::jsonb, 0, 'D’où le titre : la pluralité des mondes.', 4),
    ('4ab58d22-fd5d-5a9a-911e-2cc9d825abc4'::uuid, 'db775e93-5692-5b2b-ac37-a492d0d44206'::uuid, 'À quel spectacle Fontenelle compare-t-il l’univers ?', 'mcq', '["À un opéra dont on cherche les machines cachées","À une bataille rangée","À une bibliothèque","À un jardin à la française"]'::jsonb, 0, 'Le spectateur voit les effets, le philosophe cherche les cordes derrière le décor.', 5),
    ('591f211f-a1f5-5a53-be2f-fd4d3530df98'::uuid, 'db775e93-5692-5b2b-ac37-a492d0d44206'::uuid, 'En quelle année paraissent les Entretiens ?', 'mcq', '["1686","1748","1610","1751"]'::jsonb, 0, 'Un siècle avant l’Encyclopédie, dont l’ouvrage annonce le projet de diffusion des savoirs.', 6),
    ('37d472f0-c0fe-5e40-88d5-652567d9019d'::uuid, 'db775e93-5692-5b2b-ac37-a492d0d44206'::uuid, 'Le ton galant de l’ouvrage est une faiblesse qui trahit la rigueur scientifique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une stratégie de diffusion assumée : elle suppose que la science n’appartient pas aux seuls savants.', 7),
    ('3b71d959-ae26-54d7-8928-772c7c186778'::uuid, 'db775e93-5692-5b2b-ac37-a492d0d44206'::uuid, 'Quelle tension traverse l’œuvre selon le parcours ?', 'mcq', '["Rendre accessible sans déformer","Croire ou savoir","Obéir ou se révolter","Décrire ou raconter"]'::jsonb, 0, 'Fontenelle y répond par le dialogue et par la prudence des hypothèses.', 8),
    ('25e27674-9c5c-558f-abb1-64066815066e'::uuid, 'bb298b3b-5fc4-58aa-9d64-0f532ef8b2f1'::uuid, 'Qui est Zilia ?', 'mcq', '["Une jeune Inca enlevée par les Espagnols puis conduite en France","Une aristocrate française en voyage au Pérou","Une religieuse espagnole","Une servante de Déterville"]'::jsonb, 0, 'Son ignorance des usages français est le moteur du regard critique.', 1),
    ('8d39cd9a-d6f9-5738-a04d-6fde548e518d'::uuid, 'bb298b3b-5fc4-58aa-9d64-0f532ef8b2f1'::uuid, 'Sur quel support Zilia écrit-elle ses premières lettres ?', 'mcq', '["Des quipus, cordelettes nouées incas","Du papier de riz","Des tablettes de cire","Des feuilles de palmier"]'::jsonb, 0, 'Quand elle les a épuisés, elle poursuit en français, langue qu’elle a apprise.', 2),
    ('9e30a106-7ba3-5b5d-b0a6-08bf26b42e7f'::uuid, 'bb298b3b-5fc4-58aa-9d64-0f532ef8b2f1'::uuid, 'Quel personnage recueille Zilia en France ?', 'mcq', '["Le chevalier Déterville","Le prince Aza","Le marquis de Sévigné","Le père Ambroise"]'::jsonb, 0, 'Il l’aime, mais elle refusera de l’épouser.', 3),
    ('f1585bd7-3e0a-5548-aa37-ef529a5de712'::uuid, 'bb298b3b-5fc4-58aa-9d64-0f532ef8b2f1'::uuid, 'Comment se termine le roman ?', 'mcq', '["Zilia refuse le mariage et choisit l’étude et l’amitié","Zilia épouse Déterville","Zilia retrouve Aza et l’épouse","Zilia meurt de chagrin"]'::jsonb, 0, 'Un dénouement inouï pour l’époque, où l’héroïne finissait mariée ou morte.', 4),
    ('0002d05f-67d2-5682-9b25-f510fab6e803'::uuid, 'bb298b3b-5fc4-58aa-9d64-0f532ef8b2f1'::uuid, 'Quelle critique sociale le roman développe-t-il particulièrement ?', 'mcq', '["L’éducation des femmes, réduite aux ornements","La fiscalité royale","La politique coloniale espagnole seule","L’organisation de l’armée"]'::jsonb, 0, 'C’est la dénonciation la plus célèbre de l’œuvre.', 5),
    ('f826a3f5-392a-58fc-93d1-1041911643d5'::uuid, 'bb298b3b-5fc4-58aa-9d64-0f532ef8b2f1'::uuid, 'En quelle année paraît la première édition ?', 'mcq', '["1747","1782","1721","1759"]'::jsonb, 0, 'Une version augmentée paraît en 1752 ; le succès fut considérable.', 6),
    ('a30af5ba-5f2c-5bcb-b71a-03c1a54458ba'::uuid, 'bb298b3b-5fc4-58aa-9d64-0f532ef8b2f1'::uuid, 'Le regard étranger sert seulement à faire rire du personnage principal.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il retourne le rire contre la société décrite : ce sont les usages français qui deviennent absurdes.', 7),
    ('b85da4e1-bbf3-5669-b67c-33b0c1c8187c'::uuid, 'bb298b3b-5fc4-58aa-9d64-0f532ef8b2f1'::uuid, 'À quel genre romanesque l’œuvre appartient-elle ?', 'mcq', '["Le roman épistolaire","Le roman-mémoires","Le conte philosophique","Le roman picaresque"]'::jsonb, 0, 'La forme des lettres fait tenir ensemble satire de la société et construction du sujet.', 8),
    ('f4be60ea-4f79-5b25-9669-a579ed62ba1b'::uuid, '03ae5290-2b80-5185-b341-4637725a0923'::uuid, 'Qu’est-ce qu’une focalisation interne ?', 'mcq', '["Le récit fait voir par les yeux d’un personnage","Le narrateur sait tout de tous les personnages","Le narrateur filme de l’extérieur sans entrer dans les consciences","Le récit est raconté après coup"]'::jsonb, 0, 'La focalisation zéro donne un savoir total, la focalisation externe reste au-dehors.', 1),
    ('87a45e2b-fa52-597a-8698-b1f90b182d25'::uuid, '03ae5290-2b80-5185-b341-4637725a0923'::uuid, 'Qu’est-ce qu’un récit enchâssé ?', 'mcq', '["Un récit rapporté à l’intérieur d’un autre récit","Un récit raconté à l’envers","Un récit sans narrateur","Un récit interrompu par des descriptions"]'::jsonb, 0, 'Le dispositif installe une distance et pose la question de la fiabilité du témoin.', 2),
    ('06f86d8c-c130-52b7-9ee9-c8ab23f93541'::uuid, '03ae5290-2b80-5185-b341-4637725a0923'::uuid, 'Que désigne une ellipse narrative ?', 'mcq', '["Un moment de l’histoire passé sous silence","Un retour en arrière","Une description qui suspend l’action","Une annonce de la suite"]'::jsonb, 0, 'L’analepse revient en arrière, la pause décrit, la prolepse annonce.', 3),
    ('6e6633ee-5997-5d8a-ab10-94c4968cf00a'::uuid, '03ae5290-2b80-5185-b341-4637725a0923'::uuid, 'Quel roman du XVIIe siècle est considéré comme le premier roman d’analyse ?', 'mcq', '["La Princesse de Clèves","Manon Lescaut","Gargantua","Le Roman de Renart"]'::jsonb, 0, 'Madame de Lafayette y peint les mouvements intérieurs plus que l’action.', 4),
    ('2558c29c-eefa-57c1-af49-83c325eb9afd'::uuid, '03ae5290-2b80-5185-b341-4637725a0923'::uuid, 'Quel mouvement littéraire Zola incarne-t-il ?', 'mcq', '["Le naturalisme","Le romantisme","Le symbolisme","Le classicisme"]'::jsonb, 0, 'Il prolonge le réalisme en y ajoutant l’ambition d’une méthode scientifique.', 5),
    ('449e94d7-ed88-5ab7-bf04-9e2d3f400839'::uuid, '03ae5290-2b80-5185-b341-4637725a0923'::uuid, 'Qu’est-ce qu’un personnage « en marge » ?', 'mcq', '["Un personnage situé hors des normes sociales","Un personnage secondaire","Un personnage absent du dénouement","Un narrateur non identifié"]'::jsonb, 0, 'Criminels, courtisanes, déclassés : ils rendent visible ce que la société veut ignorer.', 6),
    ('026889e8-2806-5a4b-8bd5-8316ec0de4cb'::uuid, '03ae5290-2b80-5185-b341-4637725a0923'::uuid, 'Un récit rétrospectif est raconté au moment où l’action se déroule.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est raconté après coup, ce qui permet au narrateur de commenter et de sélectionner.', 7),
    ('941c582c-78a3-52fd-a3dc-fe7f66c74f55'::uuid, '03ae5290-2b80-5185-b341-4637725a0923'::uuid, 'Comment appelle-t-on le passage où le temps du récit épouse celui de l’histoire ?', 'mcq', '["La scène","Le sommaire","La pause","L’ellipse"]'::jsonb, 0, 'Le sommaire, à l’inverse, résume une longue durée en quelques lignes.', 8),
    ('8e32f8ef-0a25-5c52-981c-927227da479e'::uuid, '77b3245f-0b6f-54de-a901-69b1c77d7b76'::uuid, 'Qui raconte l’histoire de Des Grieux et Manon ?', 'mcq', '["Des Grieux lui-même, à un narrateur qui rapporte son récit","Manon, dans son journal","Un narrateur omniscient","Tiberge, après leur mort"]'::jsonb, 0, 'Le marquis de Renoncour recueille le récit : nous ne voyons Manon que par les yeux de Des Grieux.', 1),
    ('9e5c7531-45c7-5cd2-a105-1ed1814fda95'::uuid, '77b3245f-0b6f-54de-a901-69b1c77d7b76'::uuid, 'En quelle année le roman paraît-il ?', 'mcq', '["1731","1782","1678","1830"]'::jsonb, 0, 'Il forme le septième tome des Mémoires et aventures d’un homme de qualité.', 2),
    ('775de725-c70a-53a2-bdc5-7acd91146f32'::uuid, '77b3245f-0b6f-54de-a901-69b1c77d7b76'::uuid, 'Où Des Grieux et Manon se rencontrent-ils ?', 'mcq', '["À Amiens","À Paris","À Calais","Au Havre"]'::jsonb, 0, 'Elle allait au couvent, il était promis à l’ordre de Malte.', 3),
    ('86de532d-e5ad-56ff-8111-4151aafe497a'::uuid, '77b3245f-0b6f-54de-a901-69b1c77d7b76'::uuid, 'Où Manon meurt-elle ?', 'mcq', '["Dans le désert de Louisiane","À l’Hôpital de Paris","Sur le bateau de la déportation","À Saint-Lazare"]'::jsonb, 0, 'Des Grieux l’enterre de ses mains : c’est la dernière scène du roman.', 4),
    ('9a960a02-007d-5dc7-91c3-97274271d9d1'::uuid, '77b3245f-0b6f-54de-a901-69b1c77d7b76'::uuid, 'Quel personnage incarne la voix de la morale et de l’amitié fidèle ?', 'mcq', '["Tiberge","Lescaut","M. de B…","Synnelet"]'::jsonb, 0, 'Il est toujours écouté et jamais suivi.', 5),
    ('67728664-742f-59cc-aab2-bba389b74821'::uuid, '77b3245f-0b6f-54de-a901-69b1c77d7b76'::uuid, 'Quel est le parcours associé à l’œuvre ?', 'mcq', '["Personnages en marge, plaisirs du romanesque","Les romans de l’énergie","La célébration du monde","Individu, morale et société"]'::jsonb, 0, 'Les deux héros vivent hors des normes, et le récit tire son plaisir de cette marge.', 6),
    ('0af56000-449f-5013-9738-b5f8d18bdd88'::uuid, '77b3245f-0b6f-54de-a901-69b1c77d7b76'::uuid, 'Le roman donne accès aux pensées intimes de Manon.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle n’est jamais analysée de l’intérieur : son opacité est un choix de construction.', 7),
    ('1d6eeb2e-1aa0-51ce-ad10-ae698c0c901d'::uuid, '77b3245f-0b6f-54de-a901-69b1c77d7b76'::uuid, 'Que se passe-t-il le jour de la thèse de Des Grieux en Sorbonne ?', 'mcq', '["Manon reparaît et l’arrache à sa vocation religieuse","Il est arrêté par la police","Il apprend la mort de son père","Il rencontre Tiberge pour la première fois"]'::jsonb, 0, 'C’est la scène de la rechute, au moment même où il croyait guéri.', 8),
    ('2820ebd2-b39c-514a-8b31-b94d3f193bd0'::uuid, '0c77bc3f-4ab2-5766-b0b4-b715a12d78e2'::uuid, 'Que fait la peau de chagrin à chaque souhait exaucé ?', 'mcq', '["Elle rétrécit, et la vie de son possesseur avec elle","Elle change de couleur","Elle devient plus grande","Elle disparaît une journée"]'::jsonb, 0, 'Vouloir, c’est vivre ; vivre, c’est se consumer : c’est la loi du roman.', 1),
    ('018f477b-dd20-5bf9-8acf-cb0a6cb15c1d'::uuid, '0c77bc3f-4ab2-5766-b0b4-b715a12d78e2'::uuid, 'Comment s’appelle le héros du roman ?', 'mcq', '["Raphaël de Valentin","Eugène de Rastignac","Lucien de Rubempré","Félix de Vandenesse"]'::jsonb, 0, 'Rastignac est présent, mais comme ami cynique et conseiller.', 2),
    ('c7b3dbe7-af9c-5ccf-95cb-ad36c2fc7d17'::uuid, '0c77bc3f-4ab2-5766-b0b4-b715a12d78e2'::uuid, 'Quelles sont les trois parties du roman ?', 'mcq', '["Le Talisman, La Femme sans cœur, L’Agonie","L’Enfance, La Gloire, La Chute","Paris, Province, Exil","Le Jeu, L’Amour, La Mort"]'::jsonb, 0, 'La deuxième est un long récit rétrospectif fait par Raphaël.', 3),
    ('1ea7000b-883c-5347-886f-452d2ea4341a'::uuid, '0c77bc3f-4ab2-5766-b0b4-b715a12d78e2'::uuid, 'Qui est Fœdora ?', 'mcq', '["La comtesse incapable d’aimer, dite « la femme sans cœur »","La mère de Raphaël","Une servante amoureuse de Raphaël","La femme de l’antiquaire"]'::jsonb, 0, 'Elle incarne la société parisienne : séduisante et vide.', 4),
    ('b977ea2a-3312-5417-88cb-df9862b4cf94'::uuid, '0c77bc3f-4ab2-5766-b0b4-b715a12d78e2'::uuid, 'Que fait Raphaël au début du roman, avant d’entrer chez l’antiquaire ?', 'mcq', '["Il perd son dernier argent au jeu et veut se suicider","Il vient d’hériter d’une fortune","Il soutient sa thèse","Il se bat en duel"]'::jsonb, 0, 'Il entre chez l’antiquaire pour attendre la nuit et se jeter dans la Seine.', 5),
    ('c5ef07db-18de-57cc-89bf-807bb513b127'::uuid, '0c77bc3f-4ab2-5766-b0b4-b715a12d78e2'::uuid, 'Qui aime Raphaël d’un amour désintéressé ?', 'mcq', '["Pauline","Fœdora","Aquilina","Euphrasie"]'::jsonb, 0, 'Longtemps ignorée parce que pauvre, elle réapparaît à la fin — et c’est en la désirant qu’il meurt.', 6),
    ('4bc40d31-7e09-51c5-9e47-7cd6a2d261ab'::uuid, '0c77bc3f-4ab2-5766-b0b4-b715a12d78e2'::uuid, 'L’antiquaire a survécu longtemps grâce à sa richesse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il a survécu en ne désirant rien : il est le contre-modèle exact de Raphaël.', 7),
    ('03159c58-268e-548f-98f8-a47df3b3ad57'::uuid, '0c77bc3f-4ab2-5766-b0b4-b715a12d78e2'::uuid, 'À quel ensemble de La Comédie humaine le roman appartient-il ?', 'mcq', '["Les Études philosophiques","Les Scènes de la vie parisienne","Les Scènes de la vie de province","Les Études analytiques"]'::jsonb, 0, 'Le roman y expose une idée : la pensée et le désir usent la vie.', 8),
    ('b0e3b202-75ef-5e13-b9df-b9a3468ce381'::uuid, '9ebd037b-399b-52f4-a523-7145cf2f05f6'::uuid, 'Quels deux verbes usent la vie selon l’antiquaire ?', 'mcq', '["Vouloir et Pouvoir","Aimer et Haïr","Savoir et Comprendre","Créer et Détruire"]'::jsonb, 0, 'Seul SAVOIR laisse l’homme en repos, dit-il : c’est la thèse du roman.', 1),
    ('c346540e-6490-5f54-9893-abd0f960a85f'::uuid, '9ebd037b-399b-52f4-a523-7145cf2f05f6'::uuid, 'Que montre le roman à propos de l’énergie créatrice ?', 'mcq', '["Elle est la même force que celle qui détruit","Elle est réservée aux artistes","Elle protège du malheur","Elle s’oppose au désir"]'::jsonb, 0, 'Le génie et la ruine ont la même source : le roman ne les sépare pas.', 2),
    ('366bf0bc-1a7d-5640-9d0c-e6a4a6cd3c16'::uuid, '9ebd037b-399b-52f4-a523-7145cf2f05f6'::uuid, 'Que tente Raphaël pour ne plus faire rétrécir la peau ?', 'mcq', '["Ne plus rien désirer : régime, silence, retraite à la campagne","Vendre la peau","La brûler","La confier à l’antiquaire"]'::jsonb, 0, 'Le désir revient malgré lui, et c’est en désirant Pauline qu’il meurt.', 3),
    ('85a2017e-8188-5acf-b671-7e90afdbe2f6'::uuid, '9ebd037b-399b-52f4-a523-7145cf2f05f6'::uuid, 'Que font les savants consultés par Raphaël ?', 'mcq', '["Ils échouent tous à étirer ou à altérer la peau","Ils la font grandir","Ils refusent de l’examiner","Ils prouvent qu’elle est ordinaire"]'::jsonb, 0, 'La science moderne est ici un personnage impuissant devant la loi du désir.', 4),
    ('29de1077-ad89-5c3d-8a20-0816645fc9bd'::uuid, '9ebd037b-399b-52f4-a523-7145cf2f05f6'::uuid, 'Quel ouvrage Raphaël écrit-il dans sa mansarde ?', 'mcq', '["Une Théorie de la volonté","Un traité d’économie","Un roman autobiographique","Une histoire de France"]'::jsonb, 0, 'Elle n’intéresse personne : le roman oppose l’œuvre de l’esprit et la société de l’argent.', 5),
    ('04d37048-5d06-544e-bf03-7ccda49b954d'::uuid, '9ebd037b-399b-52f4-a523-7145cf2f05f6'::uuid, 'Quelle époque le roman peint-il en arrière-plan ?', 'mcq', '["La France des années 1830, spéculation et arrivisme","La Révolution de 1789","Le règne de Louis XIV","Le Second Empire"]'::jsonb, 0, 'Une société qui se brûle à sa propre vitesse, comme Raphaël.', 6),
    ('622ffa59-fed5-599b-afb8-f1828f74627c'::uuid, '9ebd037b-399b-52f4-a523-7145cf2f05f6'::uuid, 'Le roman condamne clairement le désir comme une faute morale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il montre le désir comme une force ambivalente : sans lui, pas de création ; avec lui, la destruction.', 7),
    ('088c5ad3-75a2-5edf-a9a0-e6735cdb2d73'::uuid, '9ebd037b-399b-52f4-a523-7145cf2f05f6'::uuid, 'Quel objet du roman rend visible l’usure de la vie ?', 'mcq', '["La peau de chagrin, mesurée au crayon","Le miroir de Fœdora","La table de jeu","Le manuscrit de Raphaël"]'::jsonb, 0, 'Chaque mesure est une confrontation avec le temps qu’il reste.', 8),
    ('193621e4-eff7-5ea6-9dad-7431c9e1bffe'::uuid, 'a6ac0a3c-b3cb-5c59-9c58-780acfbdb099'::uuid, 'De quelles années datent les deux textes réunis dans le volume ?', 'mcq', '["1908 pour Les Vrilles de la vigne, 1930 pour Sido","1930 pour les deux","1900 et 1910","1920 et 1940"]'::jsonb, 0, 'Quinze ans les séparent : ce sont deux moments d’écriture très différents.', 1),
    ('715c40bd-2137-5f90-88a8-0b06e6f7cdaf'::uuid, 'a6ac0a3c-b3cb-5c59-9c58-780acfbdb099'::uuid, 'Quelles sont les trois parties de Sido ?', 'mcq', '["Sido, Le Capitaine, Les Sauvages","La Mère, Le Jardin, Le Village","L’Enfance, Paris, Le Retour","Le Printemps, L’Été, L’Hiver"]'::jsonb, 0, 'La mère, le père, puis la fratrie : trois portraits, pas un récit continu.', 2),
    ('f0eeb18c-a716-5cd4-b69f-2bc3419838db'::uuid, 'a6ac0a3c-b3cb-5c59-9c58-780acfbdb099'::uuid, 'Que découvre-t-on à la mort du Capitaine ?', 'mcq', '["Ses volumes reliés sont vierges, sauf la dédicace à sa femme","Il avait écrit un roman célèbre","Il cachait une seconde famille","Il avait vendu la maison"]'::jsonb, 0, 'Le père poète n’a rien écrit : l’œuvre manquante hante le livre.', 3),
    ('fa12b504-a7c8-5b29-b956-ef41765ac3d6'::uuid, 'a6ac0a3c-b3cb-5c59-9c58-780acfbdb099'::uuid, 'Qui sont Toby-Chien et Kiki-la-Doucette ?', 'mcq', '["Les animaux de Colette, personnages dialoguant dans Les Vrilles de la vigne","Deux amis d’enfance","Les frères de Colette","Des personnages de théâtre"]'::jsonb, 0, 'L’animal y a le même statut de personnage que l’humain.', 4),
    ('6276dd62-8020-5f3f-9f1c-aedb33101b59'::uuid, 'a6ac0a3c-b3cb-5c59-9c58-780acfbdb099'::uuid, 'Quel est le parcours associé à l’œuvre ?', 'mcq', '["La célébration du monde","Personnages en marge, plaisirs du romanesque","Les romans de l’énergie","Crise personnelle, crise familiale"]'::jsonb, 0, 'Célébrer, chez Colette, c’est nommer précisément ce que l’on regarde.', 5),
    ('4b22a3b2-56e9-50c2-9814-f1fc550e56d3'::uuid, 'a6ac0a3c-b3cb-5c59-9c58-780acfbdb099'::uuid, 'Quel est le prénom réel de Sido ?', 'mcq', '["Sidonie","Gabrielle","Adèle","Juliette"]'::jsonb, 0, 'Sidonie Landoy, mère de Sidonie-Gabrielle Colette.', 6),
    ('df6bf028-6434-5560-8027-3503c56a2d04'::uuid, 'a6ac0a3c-b3cb-5c59-9c58-780acfbdb099'::uuid, 'Sido est une autobiographie chronologique et complète.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un récit de mémoire en trois portraits, sans continuité narrative.', 7),
    ('dabdc30e-6030-57cc-95d2-d91ebf35a15d'::uuid, 'a6ac0a3c-b3cb-5c59-9c58-780acfbdb099'::uuid, 'Quelle image donne son titre au recueil de 1908 ?', 'mcq', '["Un rossignol pris dans les vrilles de la vigne, qui chante pour ne plus s’endormir","Une vigne brûlée par le gel","Un raisin cueilli trop tôt","Un jardin abandonné"]'::jsonb, 0, 'Le chant naît d’une contrainte : c’est un art poétique en miniature.', 8),
    ('7493f672-f25f-5e66-bbc1-ae49cf81089f'::uuid, 'ad216a23-c9d1-5eac-91a7-b4753e831bcd'::uuid, 'Par quel moyen la célébration s’exprime-t-elle chez Colette ?', 'mcq', '["Par la précision des noms et des sensations","Par l’exagération lyrique","Par la description abstraite","Par le refus de décrire"]'::jsonb, 0, 'L’émerveillement naît de l’exactitude, jamais de l’effusion.', 1),
    ('3daefdc5-c653-5bfc-b01a-53a5ba43dbf3'::uuid, 'ad216a23-c9d1-5eac-91a7-b4753e831bcd'::uuid, 'La célébration du monde exclut-elle la perte ?', 'mcq', '["Non, elle s’écrit justement depuis la perte","Oui, tout est joyeux","Oui, la mort est absente du livre","Non, mais la perte reste implicite"]'::jsonb, 0, 'Mère morte, enfance enfuie, maison vendue : la lumière du livre naît de cette tension.', 2),
    ('88c99a5d-aab3-5876-b6aa-e997581faae4'::uuid, 'ad216a23-c9d1-5eac-91a7-b4753e831bcd'::uuid, 'Sous quel nom Colette a-t-elle d’abord publié ?', 'mcq', '["Willy, le nom de son mari","Sido","Gabrielle Landoy","Colette Willy dès le premier livre"]'::jsonb, 0, 'Les Vrilles de la vigne marque une étape décisive vers la signature de son seul nom.', 3),
    ('3f50b51a-5374-59c9-83c1-5294af46a55b'::uuid, 'ad216a23-c9d1-5eac-91a7-b4753e831bcd'::uuid, 'Quel statut le vivant non humain occupe-t-il dans l’œuvre ?', 'mcq', '["Celui d’une société à part entière, non d’un décor","Un simple arrière-plan","Un symbole religieux","Une métaphore du désir"]'::jsonb, 0, 'Sido sauve une chenille et refuse de tuer ; Colette prête la parole à ses bêtes.', 4),
    ('15912c3b-b68e-5cea-87d2-36ac9410faad'::uuid, 'ad216a23-c9d1-5eac-91a7-b4753e831bcd'::uuid, 'Que symbolise le rossignol pris dans les vrilles de la vigne ?', 'mcq', '["L’émancipation par le chant et l’écriture","La fragilité de la nature","L’amour malheureux","Le retour des saisons"]'::jsonb, 0, 'Il chante pour ne plus se laisser ligoter : c’est un art poétique en miniature.', 5),
    ('f33b9ea7-4ffc-54e1-8c6a-933de8157402'::uuid, 'ad216a23-c9d1-5eac-91a7-b4753e831bcd'::uuid, 'Quelle double focale traverse Sido ?', 'mcq', '["Le regard de l’enfant et celui de l’adulte qui se souvient","Celui du père et celui de la mère","Celui de la ville et celui de la campagne","Celui du narrateur et celui du lecteur"]'::jsonb, 0, 'Leur superposition constante est la source de l’émotion.', 6),
    ('f40fd67d-059f-5733-9195-c1cf113ec6f9'::uuid, 'ad216a23-c9d1-5eac-91a7-b4753e831bcd'::uuid, 'L’écriture du souvenir chez Colette est un document fidèle et vérifiable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle compose, sélectionne et invente : la vérité y est de l’ordre de la sensation.', 7),
    ('dd3e9078-8a3a-5faa-be94-c7f63b7ced50'::uuid, 'ad216a23-c9d1-5eac-91a7-b4753e831bcd'::uuid, 'En quoi Sido est-elle plus qu’un personnage ?', 'mcq', '["Elle est une manière de regarder, dont naît le style de Colette","Elle est la narratrice du récit","Elle est une figure allégorique de la France rurale","Elle est l’autrice fictive du livre"]'::jsonb, 0, 'C’est elle qui apprend à sa fille à voir : le style hérite du regard.', 8),
    ('32da6bc4-46b9-53fc-adcd-0b1075a2c22e'::uuid, '4f5dc7e1-d442-5794-9c2a-bf7dde815c93'::uuid, 'Qu’est-ce que la double énonciation au théâtre ?', 'mcq', '["Une réplique s’adresse à la fois au personnage et au public","Un personnage parle deux fois de suite","Deux personnages disent la même chose","Le narrateur commente le dialogue"]'::jsonb, 0, 'Elle rend possible l’ironie dramatique, quand le spectateur en sait plus que le personnage.', 1),
    ('fefc5b25-b2f9-5654-acd2-7900e67acd87'::uuid, '4f5dc7e1-d442-5794-9c2a-bf7dde815c93'::uuid, 'Qu’est-ce qu’une stichomythie ?', 'mcq', '["Un échange de répliques très brèves","Une longue prise de parole","Une parole dite au public seul","Une indication scénique"]'::jsonb, 0, 'Elle marque presque toujours une montée de tension.', 2),
    ('34d0bf33-51de-5406-9fa7-88e65c257caf'::uuid, '4f5dc7e1-d442-5794-9c2a-bf7dde815c93'::uuid, 'Que sont les didascalies ?', 'mcq', '["Les indications scéniques données par l’auteur","Les répliques du chœur","Les monologues du héros","Les titres des actes"]'::jsonb, 0, 'Chez Nathalie Sarraute, elles deviennent presque le cœur du texte.', 3),
    ('a7418249-5551-58f0-beba-bbb6084cf612'::uuid, '4f5dc7e1-d442-5794-9c2a-bf7dde815c93'::uuid, 'Quelles sont les trois unités du théâtre classique ?', 'mcq', '["Action, lieu, temps","Action, personnage, décor","Temps, décor, langue","Lieu, registre, genre"]'::jsonb, 0, 'Le drame romantique s’en libère explicitement.', 4),
    ('28cf23c5-300b-521d-b725-347f50ed92cc'::uuid, '4f5dc7e1-d442-5794-9c2a-bf7dde815c93'::uuid, 'Qu’est-ce qu’un aparté ?', 'mcq', '["Une parole dite au public, censée ne pas être entendue des autres personnages","Une réplique en vers","Un monologue de fin d’acte","Une réplique coupée par une autre"]'::jsonb, 0, 'C’est un ressort comique très employé, notamment par les valets.', 5),
    ('4a959c29-532b-5af5-a9a5-cd9a34207737'::uuid, '4f5dc7e1-d442-5794-9c2a-bf7dde815c93'::uuid, 'Sur quoi repose un quiproquo ?', 'mcq', '["Sur un malentendu entre les personnages","Sur un mensonge assumé","Sur une révélation finale","Sur une coïncidence de dates"]'::jsonb, 0, 'Le spectateur, lui, comprend tout : c’est ce décalage qui fait rire.', 6),
    ('bef3d659-869e-5919-beed-59a192891cb4'::uuid, '4f5dc7e1-d442-5794-9c2a-bf7dde815c93'::uuid, 'Une pièce de théâtre ne peut mêler qu’un seul registre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les basculements de registre — du rire au grinçant — sont souvent le cœur de l’analyse.', 7),
    ('d024b5af-dcb0-5a43-9712-6f91573af62a'::uuid, '4f5dc7e1-d442-5794-9c2a-bf7dde815c93'::uuid, 'Quel dramaturge du XXe siècle fait de la parole elle-même l’action de la pièce ?', 'mcq', '["Nathalie Sarraute","Pierre Corneille","Alfred de Musset","Victor Hugo"]'::jsonb, 0, 'Dans Pour un oui ou pour un non, il ne se passe rien d’autre que du langage.', 8),
    ('a0398b57-219c-5910-aa9f-672495700feb'::uuid, '4a6ae099-831b-5380-8476-e2a21b453d19'::uuid, 'De quelle ville Dorante arrive-t-il au début de la pièce ?', 'mcq', '["Poitiers","Lyon","Rouen","Bordeaux"]'::jsonb, 0, 'Il vient d’abandonner le droit pour se faire homme du monde à Paris.', 1),
    ('1d2bcf16-b0f2-5474-87a3-da52423f68bd'::uuid, '4a6ae099-831b-5380-8476-e2a21b453d19'::uuid, 'Quel mensonge Dorante invente-t-il en rencontrant Clarice ?', 'mcq', '["Qu’il revient couvert de gloire de quatre ans de guerre en Allemagne","Qu’il est le fils d’un roi","Qu’il est très riche par héritage","Qu’il est poète célèbre"]'::jsonb, 0, 'Le mensonge de guerre est le premier ; tous les autres en découlent.', 2),
    ('9cb5d5bd-0eb0-5840-934f-dc9e4baf5efe'::uuid, '4a6ae099-831b-5380-8476-e2a21b453d19'::uuid, 'Sur quel quiproquo repose l’intrigue ?', 'mcq', '["Dorante croit que celle qu’il aime s’appelle Lucrèce alors qu’elle se nomme Clarice","Dorante croit son père mort","Cliton se fait passer pour son maître","Clarice se déguise en homme"]'::jsonb, 0, 'L’erreur de nom gouverne toute la pièce et manque de le faire tuer en duel.', 3),
    ('2b2bf53a-3965-5202-b6a2-eb4f1cdbdc47'::uuid, '4a6ae099-831b-5380-8476-e2a21b453d19'::uuid, 'Qui est Cliton ?', 'mcq', '["Le valet de Dorante, témoin lucide de ses mensonges","Le père de Clarice","Le rival amoureux","Un ami d’enfance de Lucrèce"]'::jsonb, 0, 'Il commente les inventions de son maître et sert de relais au spectateur.', 4),
    ('771bb264-69d9-5f61-b3e3-a564e660eb56'::uuid, '4a6ae099-831b-5380-8476-e2a21b453d19'::uuid, 'Comment la pièce se termine-t-elle ?', 'mcq', '["Dorante épouse Lucrèce, sans avoir été puni","Dorante est banni de Paris","Dorante meurt en duel","Dorante entre dans les ordres"]'::jsonb, 0, 'Le menteur n’est ni corrigé ni châtié : c’est ce qui rend le dénouement troublant.', 5),
    ('5868fdc0-0b12-5891-bb1c-c3081fa73cbc'::uuid, '4a6ae099-831b-5380-8476-e2a21b453d19'::uuid, 'En quelle année la pièce est-elle créée ?', 'mcq', '["1644","1636","1670","1601"]'::jsonb, 0, 'Quelques années après Le Cid, du même Corneille.', 6),
    ('b677ce56-6f0d-540c-8762-37a8b6ea5b44'::uuid, '4a6ae099-831b-5380-8476-e2a21b453d19'::uuid, 'Le Menteur est une pièce en prose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une comédie en cinq actes et en vers.', 7),
    ('70b04817-58e8-5007-bd33-8809ad1c6f57'::uuid, '4a6ae099-831b-5380-8476-e2a21b453d19'::uuid, 'De quelle pièce étrangère Corneille s’inspire-t-il ?', 'mcq', '["La Verdad sospechosa d’Alarcón","La Vie est un songe de Calderón","Hamlet de Shakespeare","La Mandragore de Machiavel"]'::jsonb, 0, 'Corneille adapte librement cette comédie espagnole.', 8),
    ('84f1ed58-62ab-5664-86c8-5157a2b89c3f'::uuid, '5306782f-7190-580b-9a0e-c2563155a5b8'::uuid, 'Quel genre théâtral Musset revendique-t-il pour cette pièce ?', 'mcq', '["Le proverbe","La tragédie classique","La farce","Le vaudeville"]'::jsonb, 0, 'Publié dans Un spectacle dans un fauteuil, le texte était d’abord destiné à la lecture.', 1),
    ('03b67fad-42c0-5ca2-9847-25fb9a4d93e2'::uuid, '5306782f-7190-580b-9a0e-c2563155a5b8'::uuid, 'Pourquoi Camille refuse-t-elle d’épouser Perdican ?', 'mcq', '["Les confidences amères des religieuses lui ont fait craindre l’infidélité des hommes","Elle en aime un autre","Son père l’a promise ailleurs","Elle veut vivre seule à Paris"]'::jsonb, 0, 'Son refus vient d’une peur apprise, pas d’une indifférence.', 2),
    ('19055935-84b1-5e9b-a6ca-f0e843a4509d'::uuid, '5306782f-7190-580b-9a0e-c2563155a5b8'::uuid, 'Qui est Rosette ?', 'mcq', '["Une jeune paysanne, sœur de lait de Camille","La sœur de Perdican","Une religieuse du couvent","La fille du baron"]'::jsonb, 0, 'Elle est la seule qui ne joue pas — et la seule qui meurt.', 3),
    ('a8991529-6145-5a88-80b2-aac7faa4eaa0'::uuid, '5306782f-7190-580b-9a0e-c2563155a5b8'::uuid, 'Comment la pièce se termine-t-elle ?', 'mcq', '["Rosette meurt et Camille quitte Perdican","Camille et Perdican se marient","Perdican épouse Rosette","Camille retourne au couvent après le mariage"]'::jsonb, 0, '« Elle est morte. Adieu, Perdican ! » : l’amour est reconnu quand il devient impossible.', 4),
    ('1820c33a-9bdb-5792-bf8e-af4fd3032ea3'::uuid, '5306782f-7190-580b-9a0e-c2563155a5b8'::uuid, 'Quel rôle jouent le baron, Blazius et Bridaine ?', 'mcq', '["Un contrepoint comique et grotesque au drame des jeunes gens","Les responsables directs de la mort de Rosette","Les confidents de Camille","Les narrateurs de la pièce"]'::jsonb, 0, 'Ils forment une sorte de chœur ridicule face à la tragédie.', 5),
    ('97232537-f938-565a-81b5-e79cd43735fb'::uuid, '5306782f-7190-580b-9a0e-c2563155a5b8'::uuid, 'Que signifie le verbe « badiner » ?', 'mcq', '["Plaisanter, jouer avec les mots","Mentir","Séduire par intérêt","Renoncer"]'::jsonb, 0, 'Le titre énonce la morale de la pièce avant même qu’elle commence.', 6),
    ('021265a7-56b0-536f-a197-ec5faa3c5f25'::uuid, '5306782f-7190-580b-9a0e-c2563155a5b8'::uuid, 'La pièce mêle registres comique, lyrique et tragique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la marque du drame romantique, et le moteur de l’émotion finale.', 7),
    ('906b46cb-e891-5baf-8752-2de73ccc4c15'::uuid, '5306782f-7190-580b-9a0e-c2563155a5b8'::uuid, 'Quelle tirade célèbre Perdican prononce-t-il ?', 'mcq', '["Un éloge de l’amour humain, imparfait mais vrai","Un plaidoyer pour le couvent","Une déclaration à Rosette","Un discours contre son père"]'::jsonb, 0, '« On est souvent trompé en amour… mais on aime » : il défend l’amour contre le renoncement.', 8),
    ('2a793485-02e2-5047-a667-abebffc4f8cc'::uuid, 'fc1de1c7-fd60-5971-bf60-a137edf01eb2'::uuid, 'Combien de personnages principaux la pièce compte-t-elle ?', 'mcq', '["Deux, nommés H1 et H2","Trois","Un seul","Quatre"]'::jsonb, 0, 'Des voisins interviennent brièvement, mais l’essentiel est un face-à-face.', 1),
    ('55271a09-eb4e-576a-995d-363d45db1fae'::uuid, 'fc1de1c7-fd60-5971-bf60-a137edf01eb2'::uuid, 'Quelle phrase déclenche la rupture entre les deux amis ?', 'mcq', '["« C’est bien… ça »","« Tu as changé »","« Je ne t’aime plus »","« Tu as réussi »"]'::jsonb, 0, 'Ce n’est pas la phrase qui blesse, c’est la suspension et le ton qui l’accompagnent.', 2),
    ('32f75848-1161-5ff4-831f-116b9f9305fe'::uuid, 'fc1de1c7-fd60-5971-bf60-a137edf01eb2'::uuid, 'Qu’appelle-t-on « tropismes » chez Nathalie Sarraute ?', 'mcq', '["Les mouvements intérieurs infimes qui précèdent la parole","Les didascalies de ses pièces","Les répliques très courtes","Les personnages sans nom"]'::jsonb, 0, 'Le terme est emprunté à la biologie : son théâtre les fait remonter à la surface.', 3),
    ('4fe999ab-0206-5bf8-8727-6d9789ad4862'::uuid, 'fc1de1c7-fd60-5971-bf60-a137edf01eb2'::uuid, 'Quelle est la véritable blessure révélée par la dispute ?', 'mcq', '["La condescendance et l’écart social entre les deux hommes","Une rivalité amoureuse","Une trahison financière","Un mensonge ancien"]'::jsonb, 0, 'La vie « réussie » de l’un contre la vie « ratée » de l’autre.', 4),
    ('674224fa-2bb7-527b-ac91-d95fe430a02a'::uuid, 'fc1de1c7-fd60-5971-bf60-a137edf01eb2'::uuid, 'Comment la pièce se termine-t-elle ?', 'mcq', '["Sans résolution, sur la rupture consommée","Par une réconciliation complète","Par la mort d’un des personnages","Par l’arrivée d’un troisième ami"]'::jsonb, 0, '« C’est ça… », « oui… » : aucun fait n’explique la séparation.', 5),
    ('e9645234-8b33-5324-950e-aa72abc90e1c'::uuid, 'fc1de1c7-fd60-5971-bf60-a137edf01eb2'::uuid, 'Quel rôle jouent les silences et les points de suspension ?', 'mcq', '["Ils portent le sens : le non-dit est l’essentiel du texte","Ils marquent seulement des respirations","Ils indiquent des changements de scène","Ils signalent des apartés"]'::jsonb, 0, 'Le comédien y travaille le souffle autant que la parole.', 6),
    ('07825703-2d82-5695-a4b6-e9e1e8b346d9'::uuid, 'fc1de1c7-fd60-5971-bf60-a137edf01eb2'::uuid, 'La pièce comporte une intrigue et un décor détaillés.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ni intrigue, ni décor, ni psychologie classique : seulement une pression qui monte.', 7),
    ('68999d79-d809-5c2f-a564-f043737da14e'::uuid, 'fc1de1c7-fd60-5971-bf60-a137edf01eb2'::uuid, 'En quelle année la pièce a-t-elle été écrite ?', 'mcq', '["1982","1959","1971","1995"]'::jsonb, 0, 'Nathalie Sarraute avait alors quatre-vingt-deux ans.', 8),
    ('4c8a4487-7cdb-52a3-9ff6-6fd3b5adf068'::uuid, '261bbdd8-ec7e-5549-a22c-f4b024e36dfa'::uuid, 'Qu’est-ce qui définit une proposition ?', 'mcq', '["Un ensemble organisé autour d’un verbe conjugué","Un groupe de mots séparé par une virgule","Un sujet et un complément","Une phrase entre deux points"]'::jsonb, 0, 'C’est le nombre de verbes conjugués qui distingue phrase simple et phrase complexe.', 1),
    ('363c352f-53c2-57ba-ad97-3b947ecd96d9'::uuid, '261bbdd8-ec7e-5549-a22c-f4b024e36dfa'::uuid, '« Il sort acheter du pain » est une phrase :', 'mcq', '["Simple, car l’infinitif n’est pas un verbe conjugué","Complexe, car il y a deux verbes","Averbale","Coordonnée"]'::jsonb, 0, 'Infinitifs et participes ne comptent jamais dans le découpage en propositions.', 2),
    ('5b70e875-2818-58a6-b53d-1070a8be1037'::uuid, '261bbdd8-ec7e-5549-a22c-f4b024e36dfa'::uuid, 'Combien de verbes conjugués compte-t-on dans « il avait chanté » ?', 'mcq', '["Un seul","Deux","Aucun","Trois"]'::jsonb, 0, 'Un temps composé est une seule forme verbale conjuguée.', 3),
    ('d4a2581b-c550-5568-b9d9-db03c90eb533'::uuid, '261bbdd8-ec7e-5549-a22c-f4b024e36dfa'::uuid, 'Quelles sont les trois relations possibles entre propositions ?', 'mcq', '["Juxtaposition, coordination, subordination","Addition, opposition, conclusion","Principale, relative, complétive","Sujet, verbe, complément"]'::jsonb, 0, 'Il n’en existe pas d’autres : toute analyse commence par ce classement.', 4),
    ('e2a193ab-dcd7-5996-85ad-26afa1255770'::uuid, '261bbdd8-ec7e-5549-a22c-f4b024e36dfa'::uuid, 'Comment appelle-t-on la proposition dont dépend une subordonnée ?', 'mcq', '["La principale","L’indépendante","La coordonnée","La juxtaposée"]'::jsonb, 0, 'Une subordonnée peut elle-même en contenir une autre : c’est l’enchâssement.', 5),
    ('96b84049-d044-5284-8dd3-c699b63736fc'::uuid, '261bbdd8-ec7e-5549-a22c-f4b024e36dfa'::uuid, 'Qu’est-ce qu’une proposition indépendante ?', 'mcq', '["Une proposition qui n’a aucun lien de dépendance","Une proposition sans verbe","Une proposition qui commande une subordonnée","Une proposition entre parenthèses"]'::jsonb, 0, 'Elle peut être seule dans la phrase, ou juxtaposée, ou coordonnée à une autre.', 6),
    ('64ddb66a-3ffa-5a30-b449-dc468b8ff89c'::uuid, '261bbdd8-ec7e-5549-a22c-f4b024e36dfa'::uuid, 'Une phrase sans verbe conjugué est impossible en français.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les phrases averbales existent : « Quelle horreur ! », « Silence. »', 7),
    ('1846fa86-a540-594e-a90e-b3e0427b696d'::uuid, '261bbdd8-ec7e-5549-a22c-f4b024e36dfa'::uuid, 'Quelle est la première opération à faire pour analyser une phrase ?', 'mcq', '["Souligner les verbes conjugués","Chercher les adjectifs","Repérer la ponctuation forte","Identifier le sujet du premier verbe"]'::jsonb, 0, 'On encadre ensuite les mots subordonnants, puis on nomme.', 8),
    ('11bdd040-8ffd-58c0-8c78-ef2cebc797cd'::uuid, '221ba00f-323d-5e5c-9d14-394bb65bb68c'::uuid, 'Qu’est-ce qui relie deux propositions juxtaposées ?', 'mcq', '["Un signe de ponctuation","Une conjonction de coordination","Un pronom relatif","Une conjonction de subordination"]'::jsonb, 0, 'Virgule, point-virgule ou deux-points : le lien logique reste implicite.', 1),
    ('d071fe44-af3c-5ff1-bb7a-af053728fc9b'::uuid, '221ba00f-323d-5e5c-9d14-394bb65bb68c'::uuid, 'Quelles sont les conjonctions de coordination ?', 'mcq', '["Mais, ou, et, donc, or, ni, car","Que, quand, comme, si","Qui, que, dont, où","Puis, ensuite, cependant"]'::jsonb, 0, 'Les derniers sont des adverbes de liaison, qui coordonnent aussi mais peuvent se déplacer.', 2),
    ('99edc2c1-4b65-5e8b-a52b-64a7c6285ca7'::uuid, '221ba00f-323d-5e5c-9d14-394bb65bb68c'::uuid, 'Quelle différence y a-t-il entre « car » et « parce que » ?', 'mcq', '["« Car » coordonne, « parce que » subordonne","Aucune, ce sont des synonymes exacts","« Car » subordonne, « parce que » coordonne","« Car » introduit une conséquence"]'::jsonb, 0, 'C’est la distinction la plus fréquemment demandée à l’oral du bac.', 3),
    ('c122165f-603e-5bf3-a31f-3ece892ae905'::uuid, '221ba00f-323d-5e5c-9d14-394bb65bb68c'::uuid, 'Quel effet produit une longue série de propositions juxtaposées dans un récit ?', 'mcq', '["Une accélération de l’action","Un ralentissement du rythme","Une explication détaillée","Une mise à distance ironique"]'::jsonb, 0, 'Les rapports restant implicites, le texte va plus vite que l’explication.', 4),
    ('0566963d-8d98-5eaf-a47b-b06fc5752645'::uuid, '221ba00f-323d-5e5c-9d14-394bb65bb68c'::uuid, 'Dans « Il pleuvait, mais nous sommes sortis », quel rapport est exprimé ?', 'mcq', '["L’opposition","La cause","La conséquence","Le but"]'::jsonb, 0, '« Mais » est la conjonction adversative par excellence.', 5),
    ('5f7efd99-11ad-5bfc-88d1-f9bfaf2db68f'::uuid, '221ba00f-323d-5e5c-9d14-394bb65bb68c'::uuid, 'Les propositions coordonnées sont-elles de même rang ?', 'mcq', '["Oui, aucune ne dépend de l’autre","Non, la seconde dépend de la première","Non, la première dépend de la seconde","Cela dépend de la conjonction"]'::jsonb, 0, 'C’est ce qui les distingue de la subordination.', 6),
    ('6bf04398-4a4a-5a0a-be33-a9198af0b479'::uuid, '221ba00f-323d-5e5c-9d14-394bb65bb68c'::uuid, 'Un adverbe de liaison peut se déplacer dans la proposition.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '« Nous sommes, cependant, sortis » : une conjonction de coordination ne le permet pas.', 7),
    ('033a9035-7bce-5c26-b0ed-f82893e397a5'::uuid, '221ba00f-323d-5e5c-9d14-394bb65bb68c'::uuid, 'Que faut-il ajouter à l’identification d’une juxtaposition, à l’oral ?', 'mcq', '["Son effet dans le texte étudié","Le nom de l’auteur","La nature des verbes employés","Le nombre de syllabes"]'::jsonb, 0, 'Nommer sans interpréter ne rapporte pas les points de la question de grammaire.', 8),
    ('84bdaa6e-c110-5c9b-9a92-9f39b2f0c4a1'::uuid, '5b646f1e-452e-58bd-8e9b-3390dc586fb4'::uuid, 'Que complète une subordonnée relative ?', 'mcq', '["Un nom ou un pronom, appelé antécédent","Un verbe","Toute la proposition principale","Un adjectif"]'::jsonb, 0, 'Elle fait le travail d’un adjectif : c’est un complément de l’antécédent.', 1),
    ('04271259-7266-5157-a82c-28745e427a5d'::uuid, '5b646f1e-452e-58bd-8e9b-3390dc586fb4'::uuid, 'Quelle est la double fonction du pronom relatif ?', 'mcq', '["Il relie les propositions et occupe une fonction dans la subordonnée","Il remplace le verbe et le sujet","Il coordonne et il interroge","Il détermine et il qualifie"]'::jsonb, 0, 'C’est exactement ce qu’il faut dire à l’oral : « qui », sujet de tel verbe.', 2),
    ('55397a96-2e73-5377-ac1a-ed98da42b558'::uuid, '5b646f1e-452e-58bd-8e9b-3390dc586fb4'::uuid, 'Dans « Le livre que je lis est ancien », quelle est la fonction de « que » ?', 'mcq', '["COD du verbe « lis »","Sujet de « lis »","Complément du nom « livre »","Attribut"]'::jsonb, 0, 'On le retrouve en reformulant : je lis le livre.', 3),
    ('f9497409-24f0-5a89-ae30-aa7c0864c418'::uuid, '5b646f1e-452e-58bd-8e9b-3390dc586fb4'::uuid, 'Qu’est-ce qu’une relative explicative ?', 'mcq', '["Une relative détachée par des virgules, supprimable","Une relative indispensable au sens","Une relative introduite par « dont »","Une relative sans antécédent"]'::jsonb, 0, 'La déterminative, elle, restreint le sens et ne peut pas être supprimée.', 4),
    ('dac202ac-152e-5f8f-9f2b-2118997b224a'::uuid, '5b646f1e-452e-58bd-8e9b-3390dc586fb4'::uuid, '« Les élèves qui ont fini peuvent sortir » : que signifie l’absence de virgules ?', 'mcq', '["Seuls ceux qui ont fini peuvent sortir","Tous les élèves ont fini","Aucun élève n’a fini","La phrase est incorrecte"]'::jsonb, 0, 'La relative y est déterminative : elle restreint l’antécédent.', 5),
    ('fb0c60db-f4ad-52c8-b4f2-fcba19f2b783'::uuid, '5b646f1e-452e-58bd-8e9b-3390dc586fb4'::uuid, 'Quelle est la fonction de « où » dans « le jour où nous sommes partis » ?', 'mcq', '["Complément circonstanciel de temps","Sujet","COD","Complément du nom"]'::jsonb, 0, '« Où » peut marquer le lieu comme le temps.', 6),
    ('d9301cab-1cae-5b07-9525-74252abdb9c7'::uuid, '5b646f1e-452e-58bd-8e9b-3390dc586fb4'::uuid, 'Le pronom relatif « dont » remplace toujours un complément du nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il peut aussi remplacer un complément du verbe (« la ville dont je viens ») ou de l’adjectif.', 7),
    ('d98b8025-bc01-5d84-b9fe-2c5226b1f2c8'::uuid, '5b646f1e-452e-58bd-8e9b-3390dc586fb4'::uuid, 'Quel effet stylistique la relative produit-elle dans une longue phrase ?', 'mcq', '["Elle enchâsse les informations et construit la période","Elle accélère le récit","Elle marque une rupture logique","Elle supprime le sujet"]'::jsonb, 0, 'C’est le procédé de la phrase ample, de Bossuet à Proust.', 8),
    ('3d35cf72-3dd5-52c4-9359-9a2081b44fe6'::uuid, '6c1e6638-1bb3-5c96-a64b-3e3dde1f649c'::uuid, 'Quelle est la fonction la plus fréquente d’une complétive ?', 'mcq', '["COD du verbe de la principale","Complément circonstanciel","Complément de l’antécédent","Apposition"]'::jsonb, 0, 'Test : on peut la remplacer par « quelque chose ».', 1),
    ('78a7347c-8b29-5ed0-8ea2-79390eb0a9fc'::uuid, '6c1e6638-1bb3-5c96-a64b-3e3dde1f649c'::uuid, 'Comment distinguer « que » pronom relatif de « que » conjonction ?', 'mcq', '["Le relatif a un antécédent et une fonction, la conjonction n’en a pas","Le relatif est toujours en début de phrase","La conjonction introduit une relative","Ils sont interchangeables"]'::jsonb, 0, 'C’est la confusion la plus fréquente à l’oral du bac.', 2),
    ('e5cd5794-b0be-5d46-b184-6fe2e9247f46'::uuid, '6c1e6638-1bb3-5c96-a64b-3e3dde1f649c'::uuid, 'Quel mode emploie-t-on après un verbe de volonté ?', 'mcq', '["Le subjonctif","L’indicatif","Le conditionnel","L’impératif"]'::jsonb, 0, '« Je veux qu’il vienne » : la volonté n’assure pas la réalité du fait.', 3),
    ('24d614b8-d199-5319-8a70-e65205206934'::uuid, '6c1e6638-1bb3-5c96-a64b-3e3dde1f649c'::uuid, 'Que devient le mode dans « je ne crois pas qu’il… » ?', 'mcq', '["Il bascule au subjonctif","Il reste à l’indicatif","Il passe au conditionnel","Il passe à l’infinitif"]'::jsonb, 0, 'La négation affaiblit la certitude : c’est un point d’analyse très valorisé.', 4),
    ('43ff9077-c843-5b24-8c19-930f193618cd'::uuid, '6c1e6638-1bb3-5c96-a64b-3e3dde1f649c'::uuid, 'Dans « L’idée qu’il parte me déplaît », quelle est la fonction de la complétive ?', 'mcq', '["Complément du nom « idée »","COD","Sujet","Attribut"]'::jsonb, 0, 'La complétive ne complète pas toujours un verbe.', 5),
    ('026b281b-3c6c-5eee-8cba-d2f11dcf4c7d'::uuid, '6c1e6638-1bb3-5c96-a64b-3e3dde1f649c'::uuid, 'Comment appelle-t-on la subordonnée dans « Je me demande s’il viendra » ?', 'mcq', '["Une interrogative indirecte","Une relative","Une circonstancielle de condition","Une complétive ordinaire"]'::jsonb, 0, 'Elle est introduite par « si » et occupe la fonction de COD.', 6),
    ('2585859a-df10-563a-b8a4-b6240c996fb7'::uuid, '6c1e6638-1bb3-5c96-a64b-3e3dde1f649c'::uuid, 'Une complétive peut être sujet de la principale.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '« Qu’il soit venu m’étonne » : elle occupe alors la place du sujet.', 7),
    ('4c3eb1f7-4c94-5386-8981-5899880b9dde'::uuid, '6c1e6638-1bb3-5c96-a64b-3e3dde1f649c'::uuid, 'Quel est l’intérêt d’analyser le mode d’une complétive dans un texte ?', 'mcq', '["Il révèle le degré de certitude de celui qui parle","Il indique le temps du récit","Il détermine le genre littéraire","Il précise le niveau de langue"]'::jsonb, 0, 'Indicatif ou subjonctif : la modalité change le rapport au réel.', 8),
    ('bb061024-710f-5866-905e-53c32f4aeef3'::uuid, 'c85e2bc7-1443-5ec8-86fd-95667ae6c4da'::uuid, 'Qu’est-ce qui distingue une circonstancielle d’une complétive ?', 'mcq', '["Elle est déplaçable et souvent supprimable","Elle est introduite par « que »","Elle complète un nom","Elle est toujours en fin de phrase"]'::jsonb, 0, 'La complétive, COD du verbe, ne peut pas se déplacer.', 1),
    ('92b67b7b-e2d5-5281-8d75-0c35749cd73c'::uuid, 'c85e2bc7-1443-5ec8-86fd-95667ae6c4da'::uuid, 'Quel mode exigent les conjonctions de but comme « pour que » ?', 'mcq', '["Le subjonctif","L’indicatif","Le conditionnel","L’infinitif"]'::jsonb, 0, 'Le but n’est pas réalisé au moment où l’on parle.', 2),
    ('23a3c09c-f392-5c49-839f-4a2867f34176'::uuid, 'c85e2bc7-1443-5ec8-86fd-95667ae6c4da'::uuid, 'Quel rapport exprime « bien que » ?', 'mcq', '["La concession","La cause","La conséquence","Le temps"]'::jsonb, 0, 'Elle est suivie du subjonctif, contrairement à « alors que ».', 3),
    ('bfe28962-211d-5d6d-bd29-c8a4dfdbf06b'::uuid, 'c85e2bc7-1443-5ec8-86fd-95667ae6c4da'::uuid, 'Comment se construit l’irréel du présent ?', 'mcq', '["Imparfait dans la subordonnée, conditionnel présent dans la principale","Présent et futur","Plus-que-parfait et conditionnel passé","Futur et conditionnel"]'::jsonb, 0, '« Si tu venais, je serais content. »', 4),
    ('cf9fe744-3274-51b3-8cbd-290b85a5b15e'::uuid, 'c85e2bc7-1443-5ec8-86fd-95667ae6c4da'::uuid, 'Que ne trouve-t-on jamais après « si » de condition ?', 'mcq', '["Le futur et le conditionnel","L’imparfait","Le plus-que-parfait","Le présent"]'::jsonb, 0, 'C’est l’erreur la plus fréquente à l’écrit comme à l’oral.', 5),
    ('b6c4ccf6-e593-54a5-a496-381028db1c40'::uuid, 'c85e2bc7-1443-5ec8-86fd-95667ae6c4da'::uuid, 'Quel rapport exprime « si bien que » ?', 'mcq', '["La conséquence","La cause","Le but","La condition"]'::jsonb, 0, 'Elle est suivie de l’indicatif : la conséquence est réalisée.', 6),
    ('94b59529-f72a-5e26-899e-c07f35de3ba8'::uuid, 'c85e2bc7-1443-5ec8-86fd-95667ae6c4da'::uuid, '« Avant que » se construit avec l’indicatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il exige le subjonctif : l’action n’a pas encore eu lieu. « Après que » demande en principe l’indicatif.', 7),
    ('277c85ca-2f9f-507a-a9bf-ab8c6f52b367'::uuid, 'c85e2bc7-1443-5ec8-86fd-95667ae6c4da'::uuid, 'Que faut-il faire après avoir nommé une circonstancielle à l’oral ?', 'mcq', '["Interpréter son effet dans le texte","Donner la liste des autres conjonctions","Réciter la règle du subjonctif","Repérer les figures de style"]'::jsonb, 0, 'Une concessive montre par exemple un locuteur qui anticipe l’objection.', 8),
    ('57e88e93-41cd-55d2-a523-9f414257ee74'::uuid, '7aa1285d-7e08-5fbd-9816-1c47d571304a'::uuid, 'Sur quoi porte une interrogation totale ?', 'mcq', '["Sur toute la phrase, avec une réponse oui / non","Sur un seul élément de la phrase","Sur le sujet uniquement","Sur le complément"]'::jsonb, 0, 'L’interrogation partielle, elle, appelle une information précise.', 1),
    ('23c56188-930b-52ef-8e1f-3d048d24111b'::uuid, '7aa1285d-7e08-5fbd-9816-1c47d571304a'::uuid, 'Quels mots introduisent une interrogation partielle ?', 'mcq', '["Qui, que, où, quand, comment, pourquoi, combien, quel","Est-ce que","Si","Que et ce que"]'::jsonb, 0, 'Ils indiquent l’élément précis sur lequel porte la question.', 2),
    ('2d967961-6299-52da-8324-b548e481f200'::uuid, '7aa1285d-7e08-5fbd-9816-1c47d571304a'::uuid, 'Quelle construction interrogative appartient au registre soutenu ?', 'mcq', '["L’inversion sujet-verbe","L’intonation seule","« Est-ce que »","La question sans verbe"]'::jsonb, 0, 'Dans un texte, elle signale un registre soutenu ou une distance.', 3),
    ('f98a21f5-87c6-550e-8c9f-1005167f1927'::uuid, '7aa1285d-7e08-5fbd-9816-1c47d571304a'::uuid, 'Qu’est-ce qu’une question rhétorique ?', 'mcq', '["Une question qui n’attend pas de réponse et affirme","Une question posée à soi-même","Une question indirecte","Une question partielle"]'::jsonb, 0, '« Qui ne le sait pas ? » signifie : tout le monde le sait.', 4),
    ('bcab09ab-0cb9-552f-af09-f9037908164c'::uuid, '7aa1285d-7e08-5fbd-9816-1c47d571304a'::uuid, 'Comment nomme-t-on une question qu’un personnage se pose à lui-même ?', 'mcq', '["Une délibération","Une interrogation totale","Une interrogative indirecte","Une exclamation"]'::jsonb, 0, 'Fréquente dans le monologue théâtral, elle donne à voir l’hésitation.', 5),
    ('14b02341-e56a-5f27-b101-ea41ec2a2ba2'::uuid, '7aa1285d-7e08-5fbd-9816-1c47d571304a'::uuid, 'Quelle réponse peut appeler une interrogation totale portant sur une phrase négative ?', 'mcq', '["« Si »","« Que »","« Quoi »","« Comment »"]'::jsonb, 0, '« Tu ne viens pas ? — Si. » : c’est une particularité du français.', 6),
    ('19107e42-8507-5818-a78b-0474bcd28ce1'::uuid, '7aa1285d-7e08-5fbd-9816-1c47d571304a'::uuid, 'Une question rhétorique attend une vraie réponse de l’interlocuteur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle affirme sous forme de question : c’est une arme d’argumentation.', 7),
    ('87ca2095-5ab1-5f1c-aca6-72774e9d2c39'::uuid, '7aa1285d-7e08-5fbd-9816-1c47d571304a'::uuid, 'Quelle est la troisième étape de l’analyse d’une interrogation à l’oral ?', 'mcq', '["En déterminer la valeur : vraie question, rhétorique ou délibération","Compter les mots","Chercher le sujet inversé","Vérifier la ponctuation"]'::jsonb, 0, 'C’est celle qui montre que vous savez lire, pas seulement nommer.', 8),
    ('d5205d9f-926d-5096-bb21-ecec749cf3f3'::uuid, '3e33051e-c4ca-571e-aa55-a5e3b2c2897b'::uuid, 'Que perd une interrogation lorsqu’elle devient indirecte ?', 'mcq', '["Le point d’interrogation et l’inversion du sujet","Son sujet","Son verbe","Son mot interrogatif toujours"]'::jsonb, 0, 'Elle devient une subordonnée intégrée à la phrase.', 1),
    ('07319a1e-22e2-5702-a36f-f0d9e5a68a44'::uuid, '3e33051e-c4ca-571e-aa55-a5e3b2c2897b'::uuid, 'Par quoi « est-ce que » est-il remplacé dans l’interrogation indirecte ?', 'mcq', '["Par « si »","Par « que »","Par « ce que »","Il disparaît sans remplacement"]'::jsonb, 0, '« Je demande s’il viendra. »', 2),
    ('619b4007-72b8-50d1-b274-2804b6f3aa08'::uuid, '3e33051e-c4ca-571e-aa55-a5e3b2c2897b'::uuid, 'Comment transpose-t-on « Qu’est-ce que tu veux ? » à l’indirect ?', 'mcq', '["Je demande ce que tu veux","Je demande qu’est-ce que tu veux","Je demande que tu veux","Je demande si tu veux"]'::jsonb, 0, '« Qu’est-ce que » devient « ce que » ; « qu’est-ce qui » devient « ce qui ».', 3),
    ('07748c36-8f87-5751-930e-937556d18601'::uuid, '3e33051e-c4ca-571e-aa55-a5e3b2c2897b'::uuid, 'Quelle fonction occupe généralement une interrogative indirecte ?', 'mcq', '["COD du verbe introducteur","Complément circonstanciel","Sujet","Complément du nom"]'::jsonb, 0, 'Après demander, savoir, ignorer, se demander, chercher.', 4),
    ('5867146e-af1c-51e0-b792-b13deed9614a'::uuid, '3e33051e-c4ca-571e-aa55-a5e3b2c2897b'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["Je me demande où il va","Je me demande où est-ce qu’il va","Je me demande où va-t-il","Je me demande où va-t-il ?"]'::jsonb, 0, 'Ni inversion ni « est-ce que » dans l’interrogation indirecte.', 5),
    ('06bc365f-e910-59fa-b8c3-a716b2f7c121'::uuid, '3e33051e-c4ca-571e-aa55-a5e3b2c2897b'::uuid, 'Que devient « Où vas-tu ? » rapporté au passé ?', 'mcq', '["Il m’a demandé où j’allais","Il m’a demandé où tu vas","Il m’a demandé où vas-tu","Il m’a demandé si j’allais"]'::jsonb, 0, 'La concordance des temps et le changement de personne s’appliquent.', 6),
    ('f39679dc-9381-59ff-afb8-5a2a492dd3de'::uuid, '3e33051e-c4ca-571e-aa55-a5e3b2c2897b'::uuid, 'L’interrogation indirecte conserve le point d’interrogation.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La phrase se termine par un point : ce n’est plus une question posée, c’est une question rapportée.', 7),
    ('646f0a4a-3b14-51e7-ab74-cc7cf37d5659'::uuid, '3e33051e-c4ca-571e-aa55-a5e3b2c2897b'::uuid, 'Quel effet le passage à l’indirect produit-il dans un récit ?', 'mcq', '["Il efface la voix du personnage et installe le narrateur entre lui et le lecteur","Il rend la scène plus vivante","Il accélère l’action","Il supprime toute subordination"]'::jsonb, 0, 'Le discours direct met la question en scène ; l’indirect prend de la distance.', 8),
    ('7f82fd01-8ff9-5f0c-ba42-b1c2e2a918c3'::uuid, 'fd942bf6-ffdc-58b9-9289-f693f7374418'::uuid, 'De quoi la négation française se compose-t-elle le plus souvent ?', 'mcq', '["De deux éléments : « ne » et un second terme","D’un seul adverbe","D’un préfixe","D’une inversion du sujet"]'::jsonb, 0, '« Ne… pas », « ne… jamais », « ne… rien », « ne… personne ».', 1),
    ('bf6a1a38-2d89-58ec-b6ea-8e383ef9447e'::uuid, 'fd942bf6-ffdc-58b9-9289-f693f7374418'::uuid, 'Qu’est-ce qu’une négation partielle ?', 'mcq', '["Elle ne nie qu’un élément de la phrase","Elle porte sur toute la phrase","Elle utilise un mot négatif lexical","Elle emploie « ne » seul"]'::jsonb, 0, '« Il ne vient jamais le lundi » : il vient les autres jours.', 2),
    ('34f9da76-389f-5184-89ef-58b9eed494ea'::uuid, 'fd942bf6-ffdc-58b9-9289-f693f7374418'::uuid, 'Que signifie « Je n’ai que dix euros » ?', 'mcq', '["J’ai seulement dix euros","Je n’ai pas dix euros","Je n’ai rien","J’ai plus de dix euros"]'::jsonb, 0, '« Ne… que » est une restriction, pas une négation : c’est un piège classique.', 3),
    ('b41a09f7-7e68-52e6-9522-9e0216536ad2'::uuid, 'fd942bf6-ffdc-58b9-9289-f693f7374418'::uuid, 'Qu’est-ce qu’une négation lexicale ?', 'mcq', '["Le sens négatif est porté par le mot lui-même","Le « ne » est supprimé","La négation porte sur le verbe","La phrase est interrogative"]'::jsonb, 0, '« Impossible », « refuser », « sans », « ignorer ».', 4),
    ('22dd5fb0-86f1-542f-b3b4-8afe0a2479c3'::uuid, 'fd942bf6-ffdc-58b9-9289-f693f7374418'::uuid, 'Qu’est-ce que le « ne » explétif ?', 'mcq', '["Un « ne » qui ne nie rien, employé dans certaines subordonnées","Un « ne » oublié à l’oral","Un « ne » de restriction","Un « ne » interrogatif"]'::jsonb, 0, '« Je crains qu’il ne vienne » signifie que je crains sa venue.', 5),
    ('f37e397e-a1f5-59dd-b374-53166574d9c3'::uuid, 'fd942bf6-ffdc-58b9-9289-f693f7374418'::uuid, 'Dans quel registre le « ne » disparaît-il couramment ?', 'mcq', '["À l’oral familier","Dans la langue littéraire","Dans les textes juridiques","Dans la poésie classique"]'::jsonb, 0, '« Je viens pas » : sa présence ou son absence caractérise un personnage.', 6),
    ('204aa482-6170-512d-9c39-faedd8f95969'::uuid, 'fd942bf6-ffdc-58b9-9289-f693f7374418'::uuid, '« Ne… que » est une forme de négation totale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une négation exceptive, qui restreint au lieu de nier.', 7),
    ('b6856b52-3428-5376-b8cd-c72de76789b7'::uuid, 'fd942bf6-ffdc-58b9-9289-f693f7374418'::uuid, 'Quel effet une accumulation de négations peut-elle produire dans un portrait ?', 'mcq', '["Construire le personnage par soustraction : vide, manque, enfermement","Accélérer le récit","Marquer l’ironie du narrateur seulement","Signaler un dialogue"]'::jsonb, 0, '« Qui ne dit rien, ne demande rien, n’attend plus personne. »', 8),
    ('ef2448c5-d88b-5fa9-88b5-67796b4d1cd4'::uuid, '6fceba59-9530-5727-bafe-f784f25ee389'::uuid, 'Combien de points vaut la question de grammaire à l’oral du bac ?', 'mcq', '["2 points sur 20","5 points sur 20","1 point sur 20","4 points sur 20"]'::jsonb, 0, 'Elle est posée après l’explication linéaire, sur une phrase du texte.', 1),
    ('8f799b7a-e722-5f1b-b834-075443271100'::uuid, '6fceba59-9530-5727-bafe-f784f25ee389'::uuid, 'Quelle est la première étape de la méthode ?', 'mcq', '["Relire la phrase entière à voix haute","Nommer la subordonnée","Chercher les figures de style","Donner la fonction du sujet"]'::jsonb, 0, 'Analyser un fragment au lieu de la phrase entière fait perdre des points.', 2),
    ('568d43da-7791-505e-880d-b22042f21b93'::uuid, '6fceba59-9530-5727-bafe-f784f25ee389'::uuid, 'Comment délimite-t-on les propositions ?', 'mcq', '["En comptant les verbes conjugués","En comptant les virgules","En repérant les adjectifs","En cherchant les points-virgules"]'::jsonb, 0, 'Le nombre de verbes conjugués donne toujours le squelette de la phrase.', 3),
    ('902e9449-cf78-5380-8d10-4756e6a553b9'::uuid, '6fceba59-9530-5727-bafe-f784f25ee389'::uuid, 'Quelle étape les candidats oublient-ils le plus souvent ?', 'mcq', '["L’interprétation de l’effet dans le texte","L’identification du verbe","La lecture de la phrase","La mention du sujet"]'::jsonb, 0, 'C’est elle qui fait la différence entre 1 et 2 points.', 4),
    ('8522a0e5-7e7f-5dd3-8d5b-4466080f1572'::uuid, '6fceba59-9530-5727-bafe-f784f25ee389'::uuid, 'Que doit-on préciser pour un pronom relatif ?', 'mcq', '["Son antécédent et sa fonction dans la subordonnée","Son genre uniquement","Sa place dans la phrase","Le temps du verbe qui suit"]'::jsonb, 0, 'La double fonction du relatif est le rappel attendu par l’examinateur.', 5),
    ('c5721cdf-1f23-5e31-a0cd-f7afa3c147f3'::uuid, '6fceba59-9530-5727-bafe-f784f25ee389'::uuid, 'Que vaut-il mieux faire si l’on n’est pas sûr de tout ?', 'mcq', '["Analyser correctement ce que l’on maîtrise, sans inventer","Donner plusieurs étiquettes au hasard","Ne rien dire","Changer de phrase"]'::jsonb, 0, 'Une étiquette fausse coûte plus cher qu’une analyse partielle mais juste.', 6),
    ('598d53a3-14eb-5157-9b8a-ae51cbc7d0c7'::uuid, '6fceba59-9530-5727-bafe-f784f25ee389'::uuid, 'La question de grammaire est une épreuve séparée de l’explication du texte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle prolonge la lecture : une négation ou une subordonnée s’interprètent dans le texte étudié.', 7),
    ('632c8b81-0d1b-5bc5-a6f1-76c053e53690'::uuid, '6fceba59-9530-5727-bafe-f784f25ee389'::uuid, 'Quelle formulation est la meilleure à l’oral ?', 'mcq', '["« Subordonnée conjonctive complétive, COD du verbe croire »","« Une subordonnée avec que »","« Une proposition secondaire »","« Un complément »"]'::jsonb, 0, 'Le métalangage exact fait partie de ce qui est évalué.', 8),
    ('b4b29e04-7aff-592b-a5b2-9f0aad8f83f1'::uuid, '9df56e6c-5830-52df-b217-f30b666372eb'::uuid, 'Quelle différence y a-t-il entre nature et fonction ?', 'mcq', '["La nature est ce qu’un mot est, la fonction le rôle qu’il joue","Ce sont deux mots pour la même chose","La nature dépend de la phrase, la fonction non","La fonction concerne seulement les verbes"]'::jsonb, 0, 'Un mot change de fonction selon la phrase, jamais de classe grammaticale.', 1),
    ('c4c99827-e763-5da6-b20a-985afd28a239'::uuid, '9df56e6c-5830-52df-b217-f30b666372eb'::uuid, 'Quel test permet d’identifier un COD ?', 'mcq', '["Poser « qui ? » ou « quoi ? » après le verbe, sans préposition","Poser « à qui ? »","Vérifier qu’il est déplaçable","Chercher un verbe d’état"]'::jsonb, 0, 'Le COI, lui, se construit avec une préposition.', 2),
    ('3e07862b-3b51-5017-a272-631c353a9507'::uuid, '9df56e6c-5830-52df-b217-f30b666372eb'::uuid, 'Après quels verbes trouve-t-on un attribut du sujet ?', 'mcq', '["Les verbes d’état : être, sembler, paraître, devenir, rester","Les verbes de mouvement","Les verbes pronominaux","Les verbes impersonnels"]'::jsonb, 0, 'L’attribut qualifie le sujet et ne peut pas être supprimé.', 3),
    ('e8dad631-2d81-5a54-b66f-7d2c97f08ca1'::uuid, '9df56e6c-5830-52df-b217-f30b666372eb'::uuid, 'Qu’est-ce qu’une apposition ?', 'mcq', '["Un groupe détaché par une virgule qui désigne la même réalité que le nom","Un adjectif accolé au nom","Un complément introduit par une préposition","Un pronom relatif"]'::jsonb, 0, '« Paris, capitale de la France » : elle ralentit la phrase et met en relief.', 4),
    ('545266cd-fa8d-5dc8-97be-e11980e9bc46'::uuid, '9df56e6c-5830-52df-b217-f30b666372eb'::uuid, 'Dans « une femme heureuse », quelle est la fonction de l’adjectif ?', 'mcq', '["Épithète","Attribut du sujet","Apposition","Complément du nom"]'::jsonb, 0, 'Il devient attribut dans « cette femme est heureuse ».', 5),
    ('0c57ed5c-62d6-5960-a374-5bcb7a3602d7'::uuid, '9df56e6c-5830-52df-b217-f30b666372eb'::uuid, 'Quelle est la fonction d’une subordonnée relative ?', 'mcq', '["Complément de l’antécédent","COD du verbe","Complément circonstanciel","Attribut"]'::jsonb, 0, 'Elle complète le nom ou le pronom qui la précède.', 6),
    ('1d6a3e64-62fb-5e4a-9a07-a6635630c819'::uuid, '9df56e6c-5830-52df-b217-f30b666372eb'::uuid, 'Un complément circonstanciel est en général déplaçable.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est même le test qui le distingue d’un complément essentiel comme le COD.', 7),
    ('a5dba2aa-fd96-5594-ab79-e57e00a6aa45'::uuid, '9df56e6c-5830-52df-b217-f30b666372eb'::uuid, 'Quel effet produit un complément circonstanciel placé en tête de phrase ?', 'mcq', '["Il installe un cadre avant l’action","Il accélère le récit","Il supprime le sujet","Il marque une négation"]'::jsonb, 0, 'La grammaire sert à décrire ce que le style fait : c’est le but de l’analyse.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('francais');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('francais')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 259 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 259 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
